import type { CRDocument } from '../types';

export const docs: CRDocument[] = [
  {
    id: "basil-offertory",
    title: { en: "The Offertory", ar: "تقدمة الحمل" },
    blocks: [
      { kind: 'heading', text: { en: "Ten-Ou-Osht", ar: "تين أو أوشت" } },
      { kind: 'prayer', text: { en: "We worship the Father of light, and His only-begotten Son, and the Spirit the Paraclete, the co-essential Trinity.", ar: "نسجد لآب النور، وإبنه الوحيد، والروح المعزي، الثالوث المساوي." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'heading', text: { en: "Apinav Shopi", ar: "إبي نافشوبي" } },
      { kind: 'prayer', text: { en: "The time came to send the multitude away. Let the scribes write, let the wise men assemble, and reveal what is in the holy Scriptures.", ar: "قد حان الوقت أطلق الجميع. فليفسر المعلمون، فليجتمع الحكماء إلينا، مفسرين في الكتب المقدسة." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "The blessing of the holy Trinity, the Father, the Son, and the Holy Spirit,", ar: "وبركة الثالوث الأقدس، الآب والابن والروح القدس." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "The blessing of the Theotokos, Mary, the Mother of Jesus Christ,", ar: "وبركة والدة الإله مريم أم يسوع المسيح." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Be upon all the people, being safe in the Lord. Amen, so it shall be.", ar: "تحل على هذا لشعب كله معافين من الرب أمين يكون." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'heading', text: { en: "The Offering of the Lamb (Response)", ar: "مرد تقديم الحمل" } },
      { kind: 'prayer', text: { en: "Alleluia.", ar: "هلليلويا." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'heading', text: { en: "Kyrie Eleison (41 times)", ar: "كيرياليسون (41 مرة)" } },
      { kind: 'rubric', text: { en: "Priest: We ask You O Lamb of God who carries the sin of the world, hear us and have mercy on us, and forgive us our sins.", ar: "الكاهن: يا حمل الله يا حامل خطية العالم، إسمعنا وإرحمنا واغفر لنا خطايانا." } },
      { kind: 'prayer', text: { en: "Keria Leison (41) (Lord have mercy.)", ar: "كيري لِيسون (&#1636;&#1633;) (يا رب ارحم)." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Holy, Holy, Holy, is the Lord of Sabaoth. Heaven and earth are full of Your glory and honor. O God, the Father almighty, have mercy upon us, O Holy Trinity, have mercy upon us. O Lord, God of hosts, be with us. For we have no helper in our tribulations and adversities but You.", ar: "قدوس، قدوس، قدوس، رب الصباؤوت. السماء والأرض مملوءتان من مجدك وكرامتك. ارحمنا يا الله الآب ضابط الكل. أيها الثالوث القدوس ارحمنا. أيها الرب إله القوات كن معنا، لأنه ليس لنا معين في شدائدنا وضيقاتنا سواك." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "O God, absolve, remit, and forgive us our sins which we did willfully and unwillfully, those which we committed knowingly and unknowingly, the concealed ones and manifest ones, O Lord forgive us, for the sake of Your Holy name which is called upon us, according to Your mercy and not according to our sins.", ar: "حل واغفر واصفح لنا يا الله عن سيئاتنا، التي صنعناها بإرادتنا والتي صنعناها بغير إرادتنا، التي فعلناها بمعرفة والتي فعلناها بغير معرفة، الخفية والظاهرة. يا رب اغفرها لنا، من أجل اسمك القدوس الذي دعي علينا. كرحمتك يا رب وليس كخطايانا." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Make us worthy to pray thankfully: Our Father Who art in heaven ...", ar: "واجعلنا مستحقين أن نقول بشكر: أبانا الذي في السموات..." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'heading', text: { en: "Glory and Honour", ar: "مجدا وكرامة" } },
      { kind: 'prayer', text: { en: "Glory and honor, honor and glory to the All-holy Trinity, the Father and the Son and the Holy Spirit.", ar: "مجدا وإكراما إكراما ومجدا للثالوث القدوس الآب والإبن والروح القدس." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Peace and edification to the one, only, holy, Catholic, Apostolic Orthodox Church of God. Amen.", ar: "سلاما وبنياناً لكنيسة الله الواحدة الوحيدة المقدسة الجامعة الرسولية. آمين." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Remember, O Lord, those who have brought to You these gifts and those on whose behalf they have been brought, and those by whom they have been brought. Give them all the heavenly reward.", ar: "أذكر يا رب الذين قدموا لك هذه القرابين والذين قدمت عنهم، والذين قدمت بواسطتهم أعطهم كلهم الأجر السمائي." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Pray for these holy and Precious gifts, our sacrifices, and those who have brought them. Lord have mercy.", ar: "صلوا من أجل هذه القرابين المقدسة الكريمة وضحايانا والذين قدموها. يا رب ارحم." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'heading', text: { en: "Alleluia: This is the Day", ar: "الليلويا: هذا هو اليوم" } },
      { kind: 'prayer', text: { en: "Alleluia. This is the day that the Lord has made. Let us rejoice and be glad in it. O Lord save us. O Lord straighten our ways. Blessed is He, who comes in the name of the Lord. Alleluia. Said on all days that are not part of a fast, on all major and minor feasts, on the feasts of the cross, and the feast of Nayroz.", ar: "هلليلويا. هذا هو اليوم الذي صنعه الرب فلنفرح ونبتهج فيه. يا رب خلصنا يا رب سهل سبيلنا. مبارك الآتي باسم الرب. هلليلويا." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'heading', text: { en: "In the Name of the Father", ar: "باسم الآب" } },
      { kind: 'prayer', text: { en: "In the name of the Father and the Son and the Holy Spirit, one God. Blessed be God the Father, the Pantocrator. Amen.", ar: "باسم الآب والابن والروح القدس إله واحد. مبارك الله الآب ضابط الكل.آمين." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Amen.", ar: "آمين." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'prayer', text: { en: "Blessed be His only-begotten Son, Jesus Christ our Lord. Amen.", ar: "مبارك ابنه الوحيد يسوع المسيح ربنا. آمين." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Amen.", ar: "آمين." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'prayer', text: { en: "Blessed be the Holy Spirit, the Paraclete. Amen.", ar: "مبارك الروح القدس المعزى. آمين." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Amen. One is the holy Father, One is the holy Son, One is the holy Spirit. Amen. Blessed be the Lord God forever. Amen.", ar: "آمين. واحد هو الآب القدوس، واحد هو الابن القدوس، واحد هو الروح القدس. آمين. مبارك الرب الإله إلي الأبد. آمين." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'prayer', text: { en: "Praise the Lord, all you nations, praise Him all you peoples, for His mercy is confirmed upon us, and the truth of the Lord endures forever. Amen. Alleluia.", ar: "يا جميع الامم باركوا الرب. ولتباركه جميع الشعوب. لان رحمته ثبتت علينا. و حق الرب يدوم إلي الابد. آمين.هلليلويا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Glory to the Father and to the Son and to the Holy Spirit, now and ever and unto the ages of the ages. Amen. Alleluia.", ar: "المجد للآب والابن والروح القدس، الآن وكل اوان وإلي دهر الدهور. آمين. هلليلويا." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'heading', text: { en: "Doxa Patri", ar: "ذوكصا باترى" } },
      { kind: 'prayer', text: { en: "Glory to the Father and to the Son and to the Holy Spirit, now and ever and unto the ages of the ages. Amen. Alleluia.", ar: "المجد للآب والابن والروح القدس، الآن وكل اوان وإلي دهر الدهور. آمين. هلليلويا." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'heading', text: { en: "The Thanksgiving Prayer (Offertory)", ar: "صلاة الشكر (تقديم الحمل)" } },
      { kind: 'prayer', text: { en: "Pray.", ar: "صلوا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Stand up for prayer.", ar: "للصلاة قفوا." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'prayer', text: { en: "Peace be with You all.", ar: "السلام للكل." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "And with your spirit.", ar: "ولروحك أيضًا." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Let us give thanks to the Beneficent and Merciful God, the Father of our Lord, God, and Savior Jesus Christ.", ar: "فلنشكر صانع الخيرات الرحوم الله أبا ربنا وإلهنا ومخلصنا يسوع المسيح." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "For He has covered us, helped us, guarded us, accepted us to Himself, spared us, supported us, and has brought us to this hour.", ar: "لأنه سترنا وأعاننا وحفظنا وقبلنا إليه. وشفق علينا وعضدنا وأتي بنا إلي هذه الساعة." } },
      { kind: 'prayer', text: { en: "Let us also ask Him, the Lord our God, the Pantocrator, to guard us in all peace this holy day and all the days of our life.", ar: "هو أيضا فلنسأله أن يحفظنا في هذا اليوم المقدس، وكل أيام حياتنا بكل سلام، ضابط الكل الرب الهنا." } },
      { kind: 'prayer', text: { en: "Pray.", ar: "صلوا." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'prayer', text: { en: "Lord have mercy.", ar: "يا رب ارحم." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "O Master, Lord; God the Pantocrator, the Father of our Lord, God, and Savior Jesus Christ.", ar: "أيها السيد الرب الاله ضابط الكل أبو ربنا وإلهنا ومخلصنا يسوع المسيح." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "we thank You for everything, concerning everything, and in everything. For You have covered us, helped, us guarded us, accepted us to Yourself, spared us, supported us, and have brought us to this hour.", ar: "نشكرك علي كل حال ومن أجل كل حال وفي كل حال. لأنك سترتنا وأعنتنا وحفظتنا وقبلتنا إليك وشفقت علينا وعضدتنا، وأتيت بنا إلي هذه الساعة." } },
      { kind: 'prayer', text: { en: "Pray that God may have mercy and compassion on us, hear us, help us and accept the supplications and prayers of His saints for that which is good on our behalf at all times.", ar: "أطلبوا لكي يرحمنا الله، ويتراءف علينا، ويسمعنا، ويعيننا، ويقبل سؤالات وطلبات قديسيه منهم بالصلاح عنا في كل حين." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'prayer', text: { en: "And make us worthy to partake of the communion of His holy and blessed mysteries, for the remission of our sins.", ar: "ويجعلنا مستحقين أن ننال من شركة أسراره المقدسة المباركة، لمغفرة خطايانا." } },
      { kind: 'prayer', text: { en: "Lord have mercy.", ar: "يا رب ارحم." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Therefore, we ask and entreat Your goodness, O Lover of Mankind, grant us to complete this Holy day and all the days of our life, in all peace with Your fear.", ar: "من اجل هذا نسأل ونطلب. من صلاحك يا محب البشر امنحنا أن نكمل هذا اليوم المقدس وكل أيام حياتنا، بكل سلام مع مخافتك." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "All envy, all temptation, all the work of Satan, the council of wicked men and the rising up of enemies, hidden and manifest, take them away from us.", ar: "كل حسد وكل تجربة وكل فعل الشيطان ومؤامرة الناس الاشرار وقيام الاعداء الخفيين والظاهرين. انزعها عنا." } },
      { kind: 'prayer', text: { en: "And from all Your people, and from this church, and from this, Your holy place. But those things, which are good and profitable do provide for us, for it is You who has given us the authority to tread on serpents and scorpions, and upon all the power of the enemy.", ar: "وعن سائر شعبك. وعن هذه الكنيسة. وعن موضعك المقدس هذا. أما الصالحات والنافعات فارزقنا إياها لأنك أنت الذي أعطيتنا السلطان أن ندوس على الحيات والعقارب وكل قوة العدو." } },
      { kind: 'prayer', text: { en: "And lead us not into temptation, but deliver us from the evil one...", ar: "ولا تدخلنا في تجربة لكن نجنا من الشرير..." } },
      { kind: 'prayer', text: { en: "(Saved.) Amen. And with your spirit.", ar: "خلصت حقا ولروحك." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'heading', text: { en: "The Absolution of the Servants", ar: "تحليل الخدام" } },
      { kind: 'prayer', text: { en: "May Your servants, ministers of this day, the hegomen(s), the priest(s), the deacon(s), the clergy, all the people, and my weak self, be absolved from the mouth of the All- Holy Trinity, the Father and the Son and the Holy Spirit; and from the mouth of the one, only, Holy, Catholic and Apostolic Church.", ar: "عبيدك خدام هذا اليوم القمامصة والقسوس والشمامسة والاكليروس وكل الشعب وضعفي يكونون محاللين من فم الثالوث القدوس الآب والابن والروح القدس ومن فم الكنيسة الواحدة الوحيدة المقدسة الجامعة الرسولية." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "And from the mouths of the twelve apostles; and from the mouth of the Beholder of God the Evangelist Saint Mark, the apostle and martyr; the patriarch Saint Severus; our teacher Dioscorus, Saint Athanasius the Apostolic; Saint Peter the holy martyr and the high priest; Saint John Chrysostom; Saint Cyril.", ar: "ومن أفواه الاثني عشر رسولا ومن فم ناظر الاله الإنجيلى مرقس الرسول الطاهر والشهيد والبطريرك القديس ساويرس ومعلمنا ديوسقورس والقديس أثناسيوس الرسولي والقديس بطرس خاتم الشهداء رئيس الكهنة والقديس يوحنا ذهبي الفم والقديس كيرلس." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Saint Basil; and Saint Gregory; and from the mouths of the three hundred and eighteen assembled at Nicea; the one hundred and fifty at Constantinople, and the two hundred at Ephesus; And from the mouth of our Honored father the high priest Pope Abba Shenouda and from the mouth of my abject self.", ar: "والقديس باسيليوس والقديس اغريغوريوس ومن أفواه الثلاثمائة والثمانية عشر المجتمعين بنيقية والمئة والخمسين بالقسطنطينية والمائتين بأفسس ومن فم أبينا المكرم رئيس الكهنة البابا أنبا شنودة ومن فم حقارتي." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "For blessed and full of glory is Your holy Name, O Father and Son and Holy Spirit, now and at all times and unto the age of all ages. Amen.", ar: "انه مبارك مملوء مجدا اسمك القدوس أيها الآب والابن والروح القدس. الآن وكل أوان إلي دهر الدهور كلها آمين." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'heading', text: { en: "The Thanksgiving Prayer", ar: "صلاة الشكر" } },
      { kind: 'prayer', text: { en: "Have mercy on us, O God, the Father, the Pantocrator. All-Holy Trinity, have mercy on us.", ar: "إرحمنا يا الله الآب ضابط الكل. أيها الثالوث القدوس إرحمنا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "O Lord, God of the powers, be with us, for we have no helper in our tribulations and afflictions but You.", ar: "أيها الرب إله القوات كن معنا، لأنه ليس لنا معين في شدائدنا وضيقاتنا سواك." } },
      { kind: 'prayer', text: { en: "Make us worthy to pray thankfully:", ar: "وإجعلنا مستحقين أن نقول بشكر:" } },
      { kind: 'prayer', text: { en: "Our Father who art in heaven, hallowed be Thy name. Thy kingdom come. Thy will be done, on earth as it is in heaven. Give us this day our daily bread; and forgive us our trespasses, as we forgive those who trespass against us; and lead us not into temptation, but deliver us from the evil one. In Christ Jesus our Lord, for Thine is the kingdom and the power and the glory forever. Amen.", ar: "أبانا الذي في السموات، ليتقدس إسمك. ليأت ملكوتك. لتكن مشيئتك، كما في السماء كذلك على الأرض. خبزنا كفافنا أعطنا اليوم. وأغفر لنا ذنوبنا، كما نغفر نحن أيضاً للمذنبين إلينا. ولا تدخلنا في تجربة، لكن نجنا من الشرير. بالمسيح يسوع ربنا، لأن لك الملك والقوة والمجد إلى الأبد. آمين." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "In Christ Jesus our Lord.", ar: "بالمسيح يسوع ربنا." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Pray.", ar: "صلوا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Stand up for prayer.", ar: "للصلاة قفوا." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'prayer', text: { en: "Peace be with all.", ar: "السلام لجميعكم." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "And with your spirit.", ar: "ولروحك أيضاً." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Let us give thanks to the beneficent and merciful God, the Father of our Lord, God, and Savior Jesus Christ.", ar: "فلنشكر صانع الخيرات، الرحوم الله أبا ربنا وإلهنا ومخلصنا يسوع المسيح." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "For He has covered us, helped us, guarded us, accepted us to Himself, spared us, supported us, and has brought us to this hour.", ar: "لأنه سترنا وأعاننا وحفظنا وقبلنا إليه وشفق علينا وعضدنا وأتى بنا إلى هذه الساعة." } },
      { kind: 'prayer', text: { en: "Let us also ask Him, the Lord our God, the Pantocrator, to guard us in all peace this holy day and all the days of our life.", ar: "هو أيضاً فلنسأله أن يحفظنا في هذا اليوم المقدس، وكل أيام حياتنا بكل سلام، ضابط الكل الرب إلهنا." } },
      { kind: 'prayer', text: { en: "Let us pray.", ar: "صلوا." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'prayer', text: { en: "Lord have mercy.", ar: "يا ربُّ إرحَم." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "O Master, Lord, God the Pantocrator, the Father of our Lord, God, and Savior Jesus Christ, we thank You for everything, concerning everything, and in everything.", ar: "أيها السيد الرب الإله ضابط الكل أبو ربنا وإلهنا ومخلصنا يسوع المسيح، نشكرك على كل حال ومن أجل كل حال وفي كل حال." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "For You have covered us, helped us, guarded us, accepted us to Yourself, spared us, supported us, and have brought us to this hour.", ar: "لأنك سترتنا وأعنتنا وحفظتنا وقبلتنا إليك وشفقت علينا وعضدتنا وأتيت بنا إلى هذه الساعة." } },
      { kind: 'prayer', text: { en: "Pray that God may have mercy and compassion on us, hear us, help us and accept the supplications and prayers of His saints, for that which is good on our behalf at all times*; and forgive us our sins.", ar: "أُطلبوا لكي يرحمنا الله، ويتراءف علينا ويسمعنا، ويعيننا، ويقبل سؤالات وطلبات قديسيه منهم بالصلاح عنا في كل حين* ويغفر لنا خطايانا." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'rubric', text: { en: "* In the presence of a bishop, the following part is added:", ar: "* في حضور الأب الأسقف، يقول الشماس هذه القطعة:" } },
      { kind: 'prayer', text: { en: "And to keep the life and standing of our honored father, Pope Abba (…) and his partner in the liturgy, our father the bishop (metropolitan), Abba (...);", ar: "وأن يحفظ حياة وقيام أبينا المكرم البابا الأنبا (...)، وشريكه في الخدمة الرسولية أبينا الأسقف (المطران) أنبا (...)." } },
      { kind: 'prayer', text: { en: "Lord have mercy.", ar: "يا ربُّ إرحَم." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Therefore, we ask and entreat Your goodness, O Lover of Mankind, grant us to complete this holy day and all the days of our life in all peace with Your fear.", ar: "من أجل هذا نسأل ونطلب من صلاحك يا محب البشر، إمنحنا أن نكمل هذا اليوم المقدس وكل أيام حياتنا بكل سلام مع مخافتك." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "All envy, all temptation, all the work of Satan, the counsel of wicked men and the rising up of enemies, hidden and manifest, take them away from us, and from all Your people,", ar: "كل حسد وكل تجربة وكل فعل الشيطان ومؤامرة الناس الأشرار وقيام الأعداء الخفيين والظاهرين. إنزعها عنا، وعن سائر شعبك،" } },
      { kind: 'prayer', text: { en: "and from this church,", ar: "وعن هذه الكنيسة،" } },
      { kind: 'prayer', text: { en: "(and from this table,)", ar: "(وعن هذه المائدة،)" } },
      { kind: 'prayer', text: { en: "and from this, Your holy place.", ar: "وعن موضعك المقدس هذا." } },
      { kind: 'prayer', text: { en: "But those things which are good and profitable do provide for us, for it is You who have given us the authority to tread on serpents and scorpions, and upon all the power of the enemy.", ar: "أما الصالحات والنافعات فارزقنا إياها، لأنك أنت الذي أعطيتنا السلطان أن ندوس على الحيات والعقارب وكل قوة العدو." } },
      { kind: 'prayer', text: { en: "And lead us not into temptation, but deliver us from the evil one, by the grace, compassion and love-of-mankind, of Your only-begotten Son, our Lord, God, and Savior, Jesus Christ.", ar: "ولا تدخلنا في تجربة، لكن نجنا من الشرير. بالنعمة والرأفات ومحبة البشر اللواتي لإبنك الوحيد، ربنا وإلهنا ومخلصنا يسوع المسيح." } },
      { kind: 'prayer', text: { en: "Through whom the glory, the honor, the dominion, and the worship are due unto You, with Him and the Holy Spirit, the Giver of Life, who is of one essence with You, now and at all times, and unto the age of all ages. Amen.", ar: "هذا الذي من قبله المجد والإكرام والعزة والسجود تليق بك معه، مع الروح القدس المحيي المساوي لك. الآن وكل أوان وإلى دهر الدهور. آمين." } },
      { kind: 'rubric', text: { en: "(The priest raises the incense while the Verses of Cymbals are chanted)", ar: "(يرفع الكاهن بخور وتُرتَّل أرباع الناقوس)" } },
      { kind: 'heading', text: { en: "The Absolution to the Son", ar: "غفران الابن" } },
      { kind: 'prayer', text: { en: "O Master, Lord Jesus Christ, the only-begotten Son and Logos of God the Father, who has broken every bond of our sins through His saving, life-giving sufferings. Who breathed into the face of His holy Disciples and saintly Apostles, and said to them, “Receive the Holy Spirit. If you forgive the sins of any, they are forgiven. If you retain the sins of any, they are retained.”", ar: "أيها السيد الرب يسوع المسيح، الإبن الوحيد وكلمة الله الآب، الذي قطع كل رباطات خطايانا من قِبَل آلامه المخلصة المحيية. الذي نفخ في وجه تلاميذه القديسين ورسله الأطهار وقال لهم: \"إقبلوا الروح القدس، من غفرتم لهم خطاياهم، غُفرت لهم. ومن أمسكتموها عليهم أُمسكت.\"" }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "You also now, O our Master, have given grace through Your holy Apostles to those who for a time labor in the priesthood in Your holy Church to forgive sin upon the earth and to bind and to loose every bond of iniquity.", ar: "أنت الآن أيضاً يا سيدنا من قِبَل رسلك الأطهار، أنعمت للذين يعملون في الكهنوت كل زمان في كنيستك المقدسة أن يغفروا الخطايا على الأرض، ويربطوا ويحلوا كل رباطات الظلم." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Now also we ask and entreat Your goodness, O Lover of Mankind, for Your servants, my fathers and my brothers, and my weakness those who bow their heads before Your holy glory.", ar: "الآن أيضاً نسأل ونطلب من صلاحك يا محب البشر عن عبيدك أبائي وأخوتي وضعفي. هؤلاء المنحنين برؤوسهم أمام مجدك المقدس." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Dispense to us Your mercy and loose every bond of our sins, and if we have committed any sin against You knowingly or unknowingly, or through anguish of heart, or in deed or word, or from faintheartedness, O Master who know the weakness of men, as a Good One and Lover of Mankind, O God, grant us the forgiveness of our sins.", ar: "إرزقنا رحمتك، وأقطع كل رباطات خطايانا وإن كنا أخطأنا إليك في شيء بعِلِم، أو بغير عِلِم، أو بجزع القلب، أو بالفعل، أو بالقول، أو بصغر القلب، فأنت أيها السيد العارف بضعف البشر، كصالح ومحب البشر، اللهُمَّ أنعم لنا بغفران خطايانا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Bless us, purify us, absolve us, and all Your people. Fill us with Your fear and straighten us for Your holy good will, for You are our God, and the glory, the honor, the dominion, and the worship are due unto You, with Your good Father and the Holy Spirit, the Giver of Life, who is of one essence with You, now and at all times and unto the age of all ages. Amen.", ar: "باركنا، طهرنا، حاللنا، وحالل سائر شعبك. إملأنا من خوفك، وقومنا إلى إرادتك المقدسة الصالحة. لأنك أنت إلهنا والمجد والكرامة والعز والسجود تليق بك مع أبيك الصالح والروح القدس المحيي المساوي لك، الآن وكل أوان وإلى دهر الدهور. آمين." }, label: { en: "Priest", ar: "الكاهن" } }
    ],
  },
  {
    id: "basil-word",
    title: { en: "Liturgy of the Word", ar: "قداس الكلمة" },
    blocks: [
      { kind: 'heading', text: { en: "The Pauline Epistle", ar: "البولس" } },
      { kind: 'rubric', text: { en: "The Pauline Epistle — the reading appointed for this day.", ar: "البولس — القراءة المعينة لهذا اليوم." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'heading', text: { en: "The Catholic Epistle", ar: "الكاثوليكون" } },
      { kind: 'rubric', text: { en: "The Catholic Epistle — the reading appointed for this day.", ar: "الكاثوليكون — القراءة المعينة لهذا اليوم." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'heading', text: { en: "The Praxis", ar: "الإبركسيس" } },
      { kind: 'rubric', text: { en: "The Acts of the Apostles — the reading appointed for this day.", ar: "الإبركسيس (أعمال الرسل) — القراءة المعينة لهذا اليوم." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'heading', text: { en: "The Trisagion", ar: "الثلاث تقديسات" } },
      { kind: 'prayer', text: { en: "Holy God, holy Mighty, holy Immortal, who was born of the Virgin, have mercy upon us.", ar: "قُدُّوسٌ الله، قُدُّوسٌ القَويُّ، قُدُّوسٌ الحَيُّ الَّذي لا يَموتُ، الَّذي وُلِدَ مِنَ العَذْراءِ، إرْحَمْنا." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Holy God, holy Mighty, holy Immortal, who was crucified for us, have mercy upon us.", ar: "قُدُّوسٌ الله، قُدُّوسٌ القَويُّ، قُدُّوسٌ الحَيُّ الَّذي لا يَموتُ، الَّذي صُلِبَ عنَّا، إرْحَمْنا." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Holy God, holy Mighty, holy Immortal, who rose from the dead and ascended into the heavens, have mercy upon us.", ar: "قُدُّوسٌ الله، قُدُّوسٌ القَويُّ، قُدُّوسٌ الحَيُّ الَّذي لا يَموتُ، الذي قامَ مِنَ الأمْواتِ وصَعِدَ إلَى السَّمواتِ، إرْحَمْنا." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Glory to the Father and to the Son and the Holy Spirit, now and forever and unto the ages of all ages. Amen.", ar: "المجْدُ للآبِ والإبنِ والرُّوحِ القُدُسِ، الآنَ وكلُّ أَوان وإلَى دَهْرِ الدُّهورِ. آمين." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "O Holy Trinity, have mercy upon us. O Holy Trinity, have mercy upon us. O Holy Trinity, have mercy upon us.", ar: "أيُّها الثَّالوثُ القُدُّوسُ إرْحَمْنا. أيُّها الثَّالوثُ القُدُّوسُ إرْحَمْنا. أيُّها الثَّالوثُ القُدُّوسُ إرْحَمْنا." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Lord, forgive our sins. Lord, forgive our iniquities. Lord, forgive our transgressions. Lord, be with the sick of Your people, heal them for the sake of Your holy name. Our fathers and brethren who have slept, repose their souls.", ar: "يا رَبُّ إغْفِرْ لَنا خَطايانا. يا رَبُّ إغْفِرْ لَنا آثامَنا. يا رَبُّ إغْفِرْ لَنا زَلاَّتَنا. يا رَبُّ إفْتَقدْ مَرْضَى شَعْبكَ، إشْفِهمْ مِنْ أجْل إسْمكَ القُدُّوسِ. آباؤُنا وإخْوَتنا الَّذينَ رَقدوا، يا رَبُّ نَيِّحْ نُفوسَهُم." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "O who are alone is sinless, help us and accept our prayers. For Yours is the glory, dominion, and triple holiness. Lord have mercy. Lord have mercy. Lord bless us. Amen.", ar: "يا مَنْ هُوَ بِلا خَطيَّة، يا ربُّ إرحَمنا. يا مَنْ بِلا خَطيَّةِ، يا رَبُّ أَعِنَّا، وإقْبَلْ طَلباتِنا إلَيْكَ. لأنَّ لَكَ المجْدَ والعِزَّةَ والتَّقْديسَ المثلَّثَ. يا ربُّ إرحَم. يا ربُّ إرحَم. يا رَبُّ بارِكْ. آمين." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'heading', text: { en: "Our Father", ar: "أبانا الذي" } },
      { kind: 'prayer', text: { en: "Our Father who art in heaven, hallowed be Thy name. Thy kingdom come. Thy will be done, on earth as it is in heaven. Give us this day our daily bread; and forgive us our trespasses, as we forgive those who trespass against us; and lead us not into temptation, but deliver us from the evil one. In Christ Jesus our Lord, for Thine is the kingdom and the power and the glory forever. Amen.", ar: "أبانا الذي في السموات، ليتقدس إسمك. ليأت ملكوتك. لتكن مشيئتك، كما في السماء كذلك على الأرض. خبزنا كفافنا أعطنا اليوم. وأغفر لنا ذنوبنا، كما نغفر نحن أيضاً للمذنبين إلينا. ولا تدخلنا في تجربة، لكن نجنا من الشرير. بالمسيح يسوع ربنا، لأن لك الملك والقوة والمجد إلى الأبد. آمين." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'heading', text: { en: "Litany for the Gospel", ar: "أوشية الإنجيل" } },
      { kind: 'litany', text: { en: "Pray.", ar: "صلوا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Stand up for prayer.", ar: "للصلاة قفوا." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'litany', text: { en: "Peace be with all.", ar: "السلام لجميعكم." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "And with your spirit.", ar: "ولروحك أيضاً." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'litany', text: { en: "O Master, Lord Jesus Christ our God, who said to His saintly, honored Disciples and holy Apostles,", ar: "أيها السيد الرب يسوع المسيح إلهنا، الذي قال لتلاميذه القديسين ورسله الأطهار المكرمين:" }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "“Many prophets and righteous men have desired to see the things which you see, and have not seen them, and to hear the things which you hear and have not heard them. But as for you, blessed are your eyes, for they see, and your ears for they hear.”", ar: "\"إن أنبياء وأبراراً كثيرين إشتهوا أن يروا ما أنتم ترون ولم يروا، وأن يسمعوا ما أنتم تسمعون ولم يسمعوا. أما أنتم فطوبى لأعينكم لأنها تبصر، ولآذانكم لأنها تسمع.\"" } },
      { kind: 'litany', text: { en: "May we be worthy to hear and to act according to Your Holy Gospels, through the prayers of Your saints.", ar: "فلنستحق أن نسمع ونعمل بأناجيلك المقدسة بطلبات قديسيك." } },
      { kind: 'litany', text: { en: "Pray for the Holy Gospel.", ar: "صلوا من أجل الإنجيل المقدس." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'litany', text: { en: "Lord have mercy.", ar: "يا ربُّ إرحَم." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'litany', text: { en: "Remember also, O our Master, all those who have bidden us to remember them in our supplications and prayers which we offer up unto You, O Lord our God. Those who already fallen asleep, repose them.", ar: "أُذكر أيضاً يا سيدنا كل الذين أوصونا أن نذكرهم في تضرعاتنا وطلباتنا التي نصعدها إليك أيها الرب إلهنا. الذين سبقوا فرقدوا، نيحهم. المرضى إشفهم." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Those who are sick, heal them. For You are the life of us all, the salvation of us all, the hope of us all, the healing of us all, and the resurrection of us all.", ar: "لأنك أنت حياتنا كلنا، وخلاصنا كلنا، ورجاؤنا كلنا، وشفاؤنا كلنا، وقيامتنا كلنا." } },
      { kind: 'heading', text: { en: "Psalm of the Gospel", ar: "المزمور" } },
      { kind: 'rubric', text: { en: "The Psalm of the day, chanted before the Gospel.", ar: "مزمور اليوم، يُرتل قبل الإنجيل." } },
      { kind: 'heading', text: { en: "The Holy Gospel", ar: "الإنجيل" } },
      { kind: 'rubric', text: { en: "The Holy Gospel — the reading appointed for this day.", ar: "الإنجيل المقدس — القراءة المعينة لهذا اليوم." } },
      { kind: 'heading', text: { en: "Gospel Response", ar: "مرد الإنجيل" } },
      { kind: 'prayer', text: { en: "Let us worship our Savior, the good Lover of Mankind, for He had compassion on us, He has come and saved us.", ar: "فلنسجد لمخلصنا، محب البشر الصالح، لأنه تراءف علينا، أتى وخلصنا." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Intercede on our behalf, O the Lady of us all the Theotokos, Mary the Mother of our Savior, that He may forgive us our sins.", ar: "إشفعي فينا أمام الرب، يا سيدتنا كلنا السيدة والدة الإله، مريم أم مخلصنا، ليغفر لنا خطايانا." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Pray to the Lord on our behalf, O beholder of God the Evangelist, Abba Mark the Apostle, that He may forgive us our sins.", ar: "أطلب من الرب عنا، يا ناظر الإله الإنجيلي، مارمرقس الرسول، ليغفر لنا خطايانا." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "For blessed be the Father and the Son, and the Holy Spirit, the perfect Trinity, we worship Him and glorify Him.", ar: "لأنه مبارك الآب والإبن، والروح القدس، الثالوث الكامل، نسجد له ونمجده." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'heading', text: { en: "Introduction to the Creed", ar: "بدء قانون الإيمان" } },
      { kind: 'prayer', text: { en: "We exalt you, the Mother of the true Light, and we glorify you, O saint and Theotokos, for you brought forth unto us the Savior of the whole world; He came and saved our souls.", ar: "نُعظِّمُكِ يا أمَّ النُّورِ الحَقيقيِّ، ونُمجِّدكِ أيَّتُها العَذْراءُ القِدِّيسةُ، والِدةُ الإلهِ، لأنَّكِ وَلدْتِ لَنا مُخلِّصَ العالَم، أتَى وخَلَّصَ نُفوسَنا." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Glory to You, our Master, our King, Christ, the pride of the Apostles, the crown of the martyrs, the joy of the righteous, the steadfastness of the churches, and the forgiveness of sins.", ar: "المجْدُ لكَ يا سَيِّدُنا ومَلكُنا المسيحُ، فَخْرَ الرُّسُل، إكْليلَ الشُهداءِ، تَهْليلَ الصِدِّيقينَ، ثَباتَ الكَنائسِ، غُفْرانَ الخَطايا" }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "We proclaim the Holy Trinity in one Godhead. We worship Him. We glorify Him. Lord have mercy. Lord have mercy. Lord bless. Amen.", ar: "نُبشِّرُ بالثَّالوثِ القُدُّوسِ، لاهوتٌ واحِدٌ، نَسجُدُ لهُ ونُمجِّدهُ. يا ربُّ إرحَم. يا ربُّ إرحَم. يا رَبُّ بارِكْ. آمين." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'heading', text: { en: "The Orthodox Creed", ar: "قانون الإيمان الأرثوذكسي" } },
      { kind: 'prayer', text: { en: "We believe in one God, God the Father, the Pantocrator, who created heaven and earth, and all things, seen and unseen.", ar: "بالحقيقة نؤمن بإله واحد، الله الآب، ضابط الكل، خالق السماء والأرض، ما يُرى وما لا يُرى." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "We believe in one Lord Jesus Christ, the only-begotten Son of God, begotten of the Father before all ages.", ar: "نؤمن برب واحد يسوع المسيح، إبن الله الوحيد، المولود من الآب قبل كل الدهور." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Light out of Light, true God of true God; begotten not created, of one essence with the Father, by whom all things were made; who for us men and for our salvation, came down from heaven, and was incarnate of the Holy Spirit and of the Virgin Mary, and became man.", ar: "نور من نور، إله حق من إله حق. مولود غير مخلوق، مساوي للآب في الجوهر، الذي به كان كل شيء. هذا الذي من أجلنا نحن البشر، ومن أجل خلاصنا، نزل من السماء، وتجسد من الروح القدس ومن مريم العذراء، وتأنس." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "And He was crucified for us under Pontius Pilate, suffered and was buried. And on the third day He rose from the dead, according to the Scriptures.", ar: "وصلب عنا على عهد بيلاطس البنطي، وتألم وقبر. وقام من بين الأموات في اليوم الثالث كما في الكتب." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "He ascended into the heavens and sits at the right hand of His Father, and He is coming again in His glory to judge the living and the dead, whose kingdom shall have no end.", ar: "وصعد إلى السموات، وجلس عن يمين أبيه، وأيضاً يأتي في مجده ليدين الأحياء والأموات، الذي ليس لملكه إنقضاء." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Yes, we believe in the Holy Spirit, the Lord, the Life-Giver, who proceeds from the Father, who, with the Father and the Son, is worshippedand glorified, who spoke by the prophets.", ar: "نعم نؤمن بالروح القدس، الرب المحيي المنبثق من الآب. نسجد له ونمجده مع الآب والإبن، الناطق في الأنبياء." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "And in one holy, catholic and apostolic Church. We confess one baptism for the remission of sins.", ar: "وبكنيسة واحدة مقدسة جامعة رسولية. ونعترف بمعمودية واحدة لمغفرة الخطايا." }, label: { en: "Congregation", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "We look for the resurrection of the dead, and the life of the age to come. Amen.", ar: "وننتظر قيامة الأموات وحياة الدهر الآتي. آمين." }, label: { en: "Congregation", ar: "الشعب" } }
    ],
  },
  {
    id: "basil-anaphora",
    title: { en: "The Anaphora", ar: "الأنافورا" },
    blocks: [
      { kind: 'heading', text: { en: "The Prayer of Reconciliation", ar: "صلاة الصلح" } },
      { kind: 'prayer', text: { en: "Pray.", ar: "صلوا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Stand up for prayer.", ar: "للصلاة قفوا." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'prayer', text: { en: "Peace be with all.", ar: "السلام لجميعكم." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "And with your spirit.", ar: "ولروحك أيضاً." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "O God, the Great, the Eternal, who formed man in incorruption;", ar: "يا اللهُ العظيمُ الأبدي، الذي جَبَلَ الإنسانَ على غيرِ فسادٍ." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "and death, which entered into the world through the envy of the Devil, You have destroyed by the life-giving manifestation of Your only-begotten Son, our Lord, God, and Savior Jesus Christ.", ar: "والموتُ الذي دخلَ إلى العالمِ بحسَدِ إبليسَ هَدَمْتَهُ، بالظهورِ المحيِي الذي لإبنِكَ الوحيدِ ربِّنا وإلهِنا ومخلِّصنا يسوعَ المسيحِ." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "You have filled the earth with the heavenly peace", ar: "وملأتَ الأرضَ من السلامِ الذي من السمواتِ." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "by which the hosts of angels glorify You, saying,", ar: "هذا الذي أجنادُ الملائكةِ يمجدونَكَ به قائلين:" }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "“Glory to God in the highest, peace on earth, and good will towards men.”", ar: "\"المجدُ للهِ في الأعالي، وعلى الأرض السلامُ، وفي الناسِ المسرةُ.\"" }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Pray for perfect peace, love, and the holy apostolic kisses.", ar: "صلُّوا من أجلِ السلامِ الكاملِ، والمحبةِ، والقُبْلاتِ الطاهرةِ الرسوليةِ." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'prayer', text: { en: "Lord have mercy.", ar: "يا ربُّ إرحَم." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "According to Your good will, O God, fill our hearts with Your peace.", ar: "بمسرَّتِكَ يا الله، إملأ قلوبَنا من سلامِكَ." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Cleanse us from all blemish, all guile, all hypocrisy, all malice, and the remembrance of evil entailing death.", ar: "وطهِّرْنا من كلِّ دنسٍ، ومن كلِّ غشٍّ، ومن كلِّ رياءٍ، ومن كلِّ فعلٍ خبيثٍ، ومن تذكارِ الشرِّ الملبس الموت." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "And make us all worthy, O our Master, to greet one another with a holy kiss,", ar: "واجعلنا مستحقين كُلَّنا يا سيدّنا، أن نُقَبِّلَ بعضُنا بعضاً بقبلةٍ مقدسةٍ." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "that without falling into condemnation we may partake of Your immortal and heavenly gift in Christ Jesus our Lord.", ar: "لكي ننالَ بغير إنطراح في دينونةٍ، من موهِبَتِكَ غيرِ المائتةِ السمائيةِ، بالمسيحِ يسوعَ ربِّنا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Through whom the glory, the honor, the dominion, and the worship are due unto You, with Him and the Holy Spirit, the Giver of Life, who is of one essence with You,", ar: "هذا الذي من قِبَلِهِ المجدُ والإكرامُ والعزُّ والسجودُ تليقُ بكَ معه، ومع الروحِ القدسِ المحيِي المساوِي لكَ." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "now and at all times and unto the age of all ages. Amen.", ar: "الآنَ وكلِّ أوانٍ وإلى دهرِ الدهورِ كلِّها. آمين." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'rubric', text: { en: "(The people may chant the Adam Aspasmos)", ar: "(يمكن أن يقال الأسبسمس الأدام)" } },
      { kind: 'prayer', text: { en: "Greet one another with a holy kiss.", ar: "قبِّلوا بعضَكُمْ بعضاً بقُبلةٍ مقدسةٍ." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'prayer', text: { en: "Lord have mercy. Lord have mercy. Lord have mercy.", ar: "يا ربُّ إرحَم، يا ربُّ إرحَم ، يا ربُّ إرحَم." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Yea, Lord, who are Jesus Christ, the Son of God, hear us and have mercy upon us.", ar: "نعم يا ربُّ، الذي هو يسوعُ المسيحُ إبنُ اللهِ، إسمعْنا وإرحّمْنا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Offer in order. Stand with trembling. Look towards the East. Let us attend.", ar: "تقدموا على الرسمِ، قفوا برعدةٍ، وإلى الشرق أنظروا. ننصِتْ." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Through the intercessions of the Theotokos, Saint Mary, O Lord, grant us the forgiveness of our sins.", ar: "بشفاعاتِ والدةِ الإلهِ القديسةِ مريم، يا ربُّ أَنعِمْ لنا بمغفرةِ خطايانا." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "We worship You, O Christ, with Your good Father and the Holy Spirit, for You (have come) and saved us.", ar: "نسجدُ لكَ أيها المسيحُ، مع أبيكَ الصالح، والروحِ القدسِ، لأنكَ (أتيتَ) وخلَّصتنا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "A mercy of peace, a sacrifice of praise.", ar: "رحمةُ السلامِ، ذبيحةُ التسبيحِ." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'heading', text: { en: "The Anaphora", ar: "الأنافورا" } },
      { kind: 'prayer', text: { en: "The Lord be with you all.", ar: "الرب مع جميعكم." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "And with your spirit.", ar: "ومع روحك أيضاً." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Lift up your hearts.", ar: "إرفعوا قلوبكم." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "We have them with the Lord.", ar: "هي عند الرب." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Let us give thanks to the Lord.", ar: "فلنشكر الرب." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "It is meet and right.", ar: "مستحقٌ وعادلٌ." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Meet and right, meet and right; truly, indeed, it is meet and right.", ar: "مستحقٌ وعادلٌ، مستحقٌ وعادلٌ، لأنه حقاً بالحقيقة مستحقٌ وعادلٌ." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "O You, THE BEING, Master, Lord, God of Truth,", ar: "أيها الكائن السيد الرب الإله الحق." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "being before the ages and reigning forever;", ar: "الكائن قبل الدهـور والمـالك إلى الأبد." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "who dwell in the highest and look upon the lowly;", ar: "الساكـن في الأعالي والناظر إلى المتواضعــات." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "who have created the heaven, the earth, the sea, and all that is therein;", ar: "الـذي خلــق السماء والأرض والبحر وكل ما فيها." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "the Father of our Lord, God, and Savior Jesus Christ,", ar: "أبو ربنا وإلهنا ومخلصنا يسوع المسيح." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "by whom You have created all things, visible and invisible;", ar: "هذا الذي خلقت الكل به، ما يرى وما لا يرى." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "who sits upon the throne of His glory; and who is worshiped by all the holy powers.", ar: "الجالس على كرسى مجده، المسجود له من جميع القوات المقدسة." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "You who are seated, stand.", ar: "أيها الجلوس قفوا." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'prayer', text: { en: "Before whom stand the angels, the archangels, the principalities, the authorities, the thrones, the dominions, and the powers.", ar: "الذي يقف أمامه الملائكة ورؤساء الملائكة، والرئاسات والسلطات والكراسي، والربوبيات والقوات." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Look towards the East.", ar: "وإلى الشرق انظروا." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'prayer', text: { en: "You are He around whom stand the Cherubim full of eyes, and the Seraphim with six wings, praising continuously, without ceasing, saying—", ar: "أنت هو الذي يقف حولك الشاروبيم الممتلئون أعينا، والسِّرافيم ذوو الستة الأجنحة، يسبحون على الدوام بغير سكوت قائلين:" }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Let us attend.", ar: "ننصت." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'rubric', text: { en: "(The people may chant the Watos Aspasmos)", ar: "(يمكن أن يقال الأسبسمس الواطس)" } },
      { kind: 'prayer', text: { en: "The Cherubim worship You, and the Seraphim glorify You, proclaiming and saying,", ar: "الشاروبيم يسجدون لك، والسِّرافيم يمجدونك، صارخين قائلين:" }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "“Holy, holy, holy, Lord of hosts, heaven and earth are full of Your holy glory.”", ar: "\"قدوس. قدوس. قدوس. رب الصاباؤت. السماء والأرض مملوءتان من مجدك الأقدس.\"" }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'heading', text: { en: "Agios, Agios, Agios", ar: "أجيوس، أجيوس، أجيوس" } },
      { kind: 'prayer', text: { en: "Agios, agios, agios.", ar: "أجيوس، أجيوس، أجيوس." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Holy, holy, holy, indeed. O Lord our God, who formed us, created us, and placed us in the Paradise of joy,", ar: "قدوس، قدوس، قدوس، بالحقيقة أيها الرب إلهنا. الذي جبلنا وخلقنا ووضعنا في فردوس النعيم." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "when we disobeyed Your commandment by the deception of the serpent, we fell from eternal life and were exiled from the Paradise of joy.", ar: "وعندما خالفنا وصيتك بغواية الحية، سقطنا من الحياة الأبدية، ونفينا من فردوس النعيم." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "You have not abandoned us to the end, but have always visited us through Your holy prophets, and in the last days You manifested Yourself to us, who were sitting in darkness and the shadow of death,", ar: "لم تتركنا عنك أيضاً إلى الإنقضاء، بل تعهدتنا دائماً بأنبيائك القديسين. وفي آخر الأيام ظهرت لنا، نحن الجلوس في الظلمة وظلال الموت." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "through Your only-begotten Son, our Lord, God, and Savior Jesus Christ,", ar: "بإبنك الوحيد ربنا وإلهنا ومخلصنا يسوع المسيح." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "who, of the Holy Spirit and of the holy Virgin Mary—", ar: "هذا الذي من الروح القدس ومن العذراء القديسة مريم." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Amen.", ar: "آمين." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'heading', text: { en: "Was Incarnate and Became Man", ar: "تجسد وتأنس" } },
      { kind: 'prayer', text: { en: "was incarnate and became man, and taught us the ways of salvation.", ar: "تجسد وتأنس وعلمنا طرق الخلاص." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "He granted us the birth from on high through water and Spirit.", ar: "وأنعم علينا بالميلاد الذي من فوق بواسطة الماء والروح." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "He made us unto Himself an assembled people, and sanctified us by Your Holy Spirit. He loved His own who are in the world, and gave Himself up for our salvation unto death, which reigned over us, whereby we were bound and sold on account of our sins.", ar: "وجعلنا له شعباً مجتمعاً، وصيرنا أطهاراً بروحك القدوس. هذا الذي أحب خاصته الذين في العالم، وسلم ذاته فداءً عنا، إلى الموت الذي تملَّك علينا، هذا الذي كنا ممسكين به، مبيعين من قِبَل خطايانا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "He descended into Hades through the Cross.", ar: "نزل إلى الجحيم من قِبَل الصليب." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Amen. I believe.", ar: "حقاً. أؤمن." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'heading', text: { en: "He Rose from the Dead", ar: "وقام من الأموات" } },
      { kind: 'prayer', text: { en: "He rose from the dead on the third day.", ar: "وقام من الأموات في اليوم الثالث." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "He ascended into the heavens and sat at Your right hand, O Father.", ar: "وصعد إلى السموات، وجلس عن يمينك أيها الآب." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "He has appointed a Day for recompense, on which He will appear to judge the world in righteousness, and give each one according to his deeds.", ar: "ورسم يوماً للمجازاة، هذا الذي يظهر فيه ليدين المسكونة بالعدل، ويعطي كل واحد حسب أعماله." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "According to Your mercy, O Lord, and not according to our sins.", ar: "كرحمتك يا رب، وليس كخطايانا." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'heading', text: { en: "The Institution Narrative", ar: "الصلوات التأسيسية" } },
      { kind: 'prayer', text: { en: "He instituted for us this great Mystery of godliness.", ar: "ووضع لنا هذا السر العظيم الذي للتقوى." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "For being determined to give Himself up to death for the life of the world—", ar: "لأنه فيما هو راسم أن يسلم نفسه للموت عن حياة العالم." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "We believe.", ar: "نؤمن." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "He took bread into His holy hands, which are without spot or blemish, blessed, and life-giving.", ar: "أخذ خبزاً على يديه الطاهرتين، اللتين بلا عيب ولا دنس، الطوباويتين المحييتين." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "We believe that this is true. Amen.", ar: "نؤمن أن هذا هو بالحقيقة. آمين." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "He looked up towards heaven to You, O God, who are His Father and Master of everyone.", ar: "ونظر إلى فوق نحو السماء، إليك يا الله أباه وسيد كل أحد." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "And when He had given thanks—", ar: "وشكر." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Amen.", ar: "آمين." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "He blessed it—", ar: "وباركه." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Amen.", ar: "آمين." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "He sanctified it.", ar: "وقدسه." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Amen.", ar: "آمين." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "We believe, we confess, and we glorify.", ar: "نؤمن ونعترف ونمجد." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "He broke it, and gave it to His own holy disciples and saintly apostles, saying,", ar: "وقسمه، وأعطاه لتلاميذه القديسين ورسله الأطهار قائلاً:" }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "“Take, eat of it, all of you.", ar: "\"خذوا كلوا منه كلكم،" }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "For this is My Body, which is broken for you and for many, to be given for the remission of sins. This do in remembrance of Me.”", ar: "لأن هذا هو جسدي الذي يقسم عنكم وعن كثيرين، يعطى لمغفرة الخطايا، هذا اصنعوه لذكري.\"" }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "This is true. Amen.", ar: "هذا هو بالحقيقة. آمين." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Likewise also, the cup, after supper, He mixed it of wine and water.", ar: "هكذا الكأس أيضاً، بعد العشاء، مزجها من خمر وماء." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "And when He had given thanks—", ar: "وشكر." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Amen.", ar: "آمين." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "He blessed it—", ar: "وباركه." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Amen.", ar: "آمين." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "He sanctified it.", ar: "وقدسه." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Amen.", ar: "آمين." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Again, we believe, we confess, and we glorify.", ar: "وأيضاً نؤمن ونعترف ونمجد." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "He tasted, and gave it also to His own holy disciples and saintly apostles, saying,", ar: "وذاق، وأعطاها أيضاً لتلاميذه القديسين ورسله الأطهار قائلاً:" }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "“Take, drink of it, all of you.", ar: "\"خذوا اشربوا منه كلكم" }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "For this is My Blood of the New Covenant, which is shed for you and for many, to be given for the remission of sins. This do in remembrance of Me.”", ar: "لأن هذا هو دمي الذي للعهد الجديد، الذي يُسفَك عنكم وعن كثيرين يعطى لمغفرة الخطايا. هذا إصنعوه لذكري.\"" }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "This is also true. Amen.", ar: "هذا هو أيضاً بالحقيقة. آمين." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "“For every time you eat of this bread and drink of this cup, you proclaim My Death, confess My Resurrection, and remember Me till I come.”", ar: "لأن كل مرة تأكلون من هذا الخبز. وتشربون من هذه الكأس. تبشرون بموتي وتعترفون بقيامتي وتذكروني إلى أن أجئ." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Amen. Amen. Amen. Your Death, O Lord, we proclaim; Your holy Resurrection and Ascension into the heavens, we confess.", ar: "آمين. آمين. آمين. بموتك يا رب نبشر، وبقيامتك المقدسة وصعودك إلى السموات، نعترف." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "We praise You, we bless You, we thank You, O Lord, and we entreat You, O our God.", ar: "نسبحك، نباركك، نشكرك يا رب ونتضرع إليك يا إلهنا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Therefore, as we also commemorate His holy Passion, His Resurrection from the dead, His Ascension into the heavens, His Sitting at Your right hand, O Father,", ar: "ففيما نحن أيضاً نصنع ذكر آلامه المقدسة، وقيامته من الأموات، وصُعوده إلى السموات، وجلوسه عن يمينك أيها الآب." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "and His Second Coming from the heavens, awesome and full of glory,", ar: "وظهوره الثاني الآتي من السموات، المخوف المملوء مجداً." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "we offer unto You Your gifts from what is Yours, for everything, concerning everything, and in everything.", ar: "نقرِّب لك قرابينك من الذي لك، على كل حال، ومن أجل كل حال وفي كل حال." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Worship God in fear and trembling.", ar: "اسجدوا لله بخوف ورعدة." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'prayer', text: { en: "We praise You, we bless You, we serve You, we worship You.", ar: "نسبحك. نباركك. نخدمك. نسجد لك." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'heading', text: { en: "The Descent of the Holy Spirit", ar: "نزول الروح القدس" } },
      { kind: 'prayer', text: { en: "And we ask You, O Lord our God—we Your sinful and unworthy servants,", ar: "نسألك أيها الرب إلهنا نحن عبيدك الخطاة، غير المستحقين،" }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "we worship You by the pleasure of Your goodness—", ar: "نسجد لك بمسرة صلاحك،" }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "that Your Holy Spirit descend upon us and upon these gifts set forth, and purify them, change them, and manifest them as a sanctification of Your saints.", ar: "وليحل روحك القدوس علينا وعلى هذه القرابين الموضوعة ويطهرها، وينقلها، ويظهرها قدساً لقديسيك." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Let us attend. Amen.", ar: "نُنصت. آمين." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'prayer', text: { en: "And this bread He makes into His holy Body.", ar: "وهذا الخبز يجعله جسداً مقدساً له." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "I believe. Amen.", ar: "أؤمن." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Our Lord, God, and Savior Jesus Christ,", ar: "ربنا وإلهنا ومخلصنا يسوع المسيح." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "given for the remission of sins and eternal life to those who partake of Him.", ar: "يُعطَى لغفرانِ الخطايا، وحياة أبدية لمَنْ يتناول منه." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "And this cup also, the precious Blood of His New Covenant.", ar: "وهذه الكأس أيضاً دماً كريماً للعهد الجديد الذي له." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Again, I believe. Amen.", ar: "وأيضاً أؤمن." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Our Lord, God, and Savior Jesus Christ, given for the remission of sins", ar: "ربنا وإلهنا ومخلصنا يسوع المسيح. يُعطَى لغفرانِ الخطايا،" }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "and eternal life to those who partake of Him.", ar: "وحياة أبدية لمَنْ يتناول منه." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Lord have mercy (3)ز", ar: "يا ربُّ إرحَم (3)." }, label: { en: "People", ar: "الشعب" } }
    ],
  },
  {
    id: "basil-litanies",
    title: { en: "Litanies & Commemorations", ar: "الأواشي والتذكارات" },
    blocks: [
      { kind: 'heading', text: { en: "The Seven Short Litanies", ar: "السبع أواشي الصغار" } },
      { kind: 'litany', text: { en: "Make us all worthy, O our Master, to partake of Your Holies, unto the purification of our souls, our bodies, and our spirits,", ar: "اجعلنا مستحقين كلنا، يا سيدنا، أن نتناول من قُدساتك طهارةً لأنفسنا وأجسادنا وأرواحنا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "that we may become one body and one spirit, and may have a share and an inheritance with all the saints who have pleased You since the beginning.", ar: "لكي نكون جسداً واحداً، وروحاً واحداً، ونجد نصيباً وميراثاً مع جميع القديسين الذين أرضوك منذ البدء." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Remember, O Lord, the peace of Your one, only, holy, catholic, and apostolic Church—", ar: "أذكر يا رب سلام كنيستك الواحدة، الوحيدة المقدسة، الجامعة الرسولية." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Pray for the peace of the one holy catholic and apostolic orthodox Church of God.", ar: "صلوا من أجل سلام الواحدة المقدسة الجامعة الرسولية كنيسة الله الأرثوذكسية." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'litany', text: { en: "Lord have mercy.", ar: "يا ربُّ إرحَم." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'litany', text: { en: "this, which You have acquired to Yourself with the precious Blood of Your Christ,", ar: "هذه التي اقتنيتها لك بالدم الكريم الذي لمسيحك." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "keep her in peace, with all the orthodox bishops who are in her.", ar: "إحفظها بسلام، وكل الأساقفة الأرثوذكسيين الذين فيها." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Foremost remember, O Lord, our blessed and honored father, the archbishop, our patriarch, Abba (…),", ar: "وأولاً اذكر يا رب بطريركنا الأب المكرم رئيس الكهنة البابا المعظم أنبا (...)،" }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "and his spiritual brothers, the Patriarch of Antioch Mar Ignatius (…), and the Patriarch of Eritrea Abouna (…).", ar: "وأخوية الروحيين مار إغناطيوس (...) بطريرك أنطاكية وأبونا (...) بطريرك إريتريا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'rubric', text: { en: "In the presence of a bishop:", ar: "في حضور الأب الأسقف:" } },
      { kind: 'litany', text: { en: "and his partner in the liturgy, our father the bishop (metropolitan), Abba (...).", ar: "وشريكة في الخدمة الرسولية أبينا الأسقف (المطران) الأنبا (...)." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'litany', text: { en: "Pray for our high priest, Pope Abba (…), pope and patriarch and archbishop of the great city of Alexandria,", ar: "صلوا من أجل رئيس كهنتنا البابا أنبا (...)، بابا وبطريرك ورئيس أساقفة المدينة العظمى الاسكندرية،" }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'litany', text: { en: "and his spiritual brothers, the Patriarch of Antioch Mar Ignatius (…), and the Patriarch of Eritrea Abouna (…).", ar: "وأخوية الروحيين مار إغناطيوس (...) بطريرك أنطاكية وأبونا (...) بطريرك إريتريا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'rubric', text: { en: "In the presence of a bishop:", ar: "في حضور الأب الأسقف:" } },
      { kind: 'litany', text: { en: "and his partner in the liturgy, our father the bishop (metropolitan), Abba (...).", ar: "وشريكة في الخدمة الرسولية أبينا الأسقف (المطران) الأنبا (...)." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'rubric', text: { en: "And concludes with:", ar: "وينهي:" } },
      { kind: 'rubric', text: { en: "and for our orthodox bishops.", ar: "وسائر أساقفتنا الارثوذكسيين." } },
      { kind: 'rubric', text: { en: "People: Lord have mercy.", ar: "الشعب: يا ربُّ إرحَم." } },
      { kind: 'rubric', text: { en: "Priest: And those who rightly divide the word of truth with him,", ar: "الكاهن: والذين يفصلون معه كلمة الحق بإستقامة." } },
      { kind: 'rubric', text: { en: "grant them unto Your holy Church to shepherd Your flock in peace.", ar: "أنعم بهم على كنيستك المقدسة يرعون قطيعك بسلام." } },
      { kind: 'rubric', text: { en: "Remember, O Lord, the orthodox hegumens, priests, and deacons.", ar: "أذكر يارب القمامصة، والقسوس الأرثوذكسيين والشمامسة." } },
      { kind: 'rubric', text: { en: "Deacon: Pray for the hegumens, priests, deacons, subdeacons, and the seven orders of the Church of God.", ar: "الشماس: صلوا من أجل القمامصة القسوس والشمامسة والإبوذياقونين وسبع طغمات كنيسة الله." } },
      { kind: 'rubric', text: { en: "People: Lord have mercy.", ar: "الشعب: يا ربُّ إرحَم." } },
      { kind: 'rubric', text: { en: "Priest: And all the servants, and all who are in virginity, and the purity of all Your faithful people.", ar: "الكاهن: وكل الخدام، وكل الذين في البتولية وطهارة كل شعبك المؤمن." } },
      { kind: 'rubric', text: { en: "(Remember, O Lord, to have mercy upon us all.)", ar: "(أذكر يا رب أن ترحمنا كلنا معاً)." } },
      { kind: 'rubric', text: { en: "People: Have mercy upon us, O God, the Father, the Pantocrator.", ar: "الشعب: إرحمنا يا الله الآب، ضابط الكل." } },
      { kind: 'rubric', text: { en: "Priest: Remember, O Lord, the salvation of this, Your holy place, and every place, and every monastery of our orthodox fathers.", ar: "الكاهن: اذكر يا رب خلاص هذا الموضع المقدس الذي لك، وكل المواضع، وكل أديرة آبائنا الأرثوذكسيين." } },
      { kind: 'rubric', text: { en: "Deacon: Pray for the salvation of the world and of this city of ours and of all cities, districts, islands, and monasteries.", ar: "الشماس: صلوا من أجل خلاص العالم، ومدينتنا هذه، وسائر المدن والأقاليم والجزائر والأديرة." } },
      { kind: 'rubric', text: { en: "People: Lord have mercy.", ar: "الشعب: يا ربُّ إرحَم." } },
      { kind: 'rubric', text: { en: "Priest: And those who dwell therein in God’s faith.", ar: "الكاهن: والساكنين فيها بإيمان الله." } },
      { kind: 'rubric', text: { en: "The priest says the appropriate litany according to the season, either the Litany of the Waters, the Litany of the Plants, or the Litany of the Fruits, or the combined litany for all three seasons.", ar: "يقول الكاهن ما يوافق الموسم من أوشية المياه أو أوشية الزروع أو أوشية الثمار أو الاوشية للثلاث معاً." } },
      { kind: 'rubric', text: { en: "From Paoni 12 to Paapi 9 (June 19 to October 19/20), the Litany of the Waters is said:", ar: "من 12 بؤونة إلى 9 بابة (19 يونيو - 19/20 أكتوبر)، تقال أوشية المياه:" } },
      { kind: 'rubric', text: { en: "Priest:  Graciously accord, O Lord, to bless the waters of the river this year.", ar: "الكاهن: تفضل يا رب مياه النهر في هذه السنة، باركها." } },
      { kind: 'rubric', text: { en: "Deacon: Pray for the rising of the waters of the rivers this year, that Christ our God may bless them and raise them according to their measure, that He may give joy to the face of the earth, sustain us, the sons of men, save the cattle, and forgive us our sins.", ar: "الشماس: أُطلبوا عن صعود مياه الأنهار في هذا السنة، لكيْ يباركها المسيح إلهنا، ويصعدها كمقدارها، ويفرِّح وجه الأرض، ويعولنا نحن بني البشر، ويعطي النجاة للبهائم، ويغفر لنا خطايانا." } },
      { kind: 'rubric', text: { en: "People: Lord have mercy (3).", ar: "الشعب: يا ربُّ إرحَم (3)." } },
      { kind: 'rubric', text: { en: "From Paapi 10 to Tobi 10 (October 20/21 to January 18/19), the Litany of the Plants is said.", ar: "من 10 بابه إلى 10 طوبة (20/21 أكتوبر - 18/19 يناير)، تقال أوشية الزروع." } },
      { kind: 'rubric', text: { en: "Priest: Graciously accord, O Lord, to bless the seeds, the herbs, and the plants of the field this year.", ar: "الكاهن: تفضل يا رب، الزروع والعشب ونبات الحقل في هذه السنة، باركها." } },
      { kind: 'rubric', text: { en: "Deacon: Pray for the seeds, the herbs, and the plants of the field this year, that Christ our God may bless them to grow and multiply unto perfection with great fruit, have compassion on His creation which His hands have made, and forgive us our sins.", ar: "الشماس: أُطلبوا عن الزروع والعشب ونبات الحقل، في هذه السنة، لكيْ يباركها المسيح إلهنا، لتنمو وتكثر إلى أن تكمل بثمرة عظيمة، ويتحنن على جبلته التي صنعتها يداه، ويغفر لنا خطايانا." } },
      { kind: 'rubric', text: { en: "People: Lord have mercy (3).", ar: "الشعب: يا ربُّ إرحَم (3)." } },
      { kind: 'rubric', text: { en: "From Tobi 11 to Paoni 11 (January 19/20 to June 18), the Litany of the Fruits is said.", ar: "من 11 طوبة إلى 11 بوؤنه (19/20 يناير - 18 يونيو)، تقال أوشية الثمار." } },
      { kind: 'rubric', text: { en: "Priest: Graciously accord, O Lord, to bless the air of heaven and the fruits of the earth this year.", ar: "الكاهن: تفضل يا رب أهوية السماء وثمرات الأرض، في هذه السنة، باركها." } },
      { kind: 'rubric', text: { en: "Deacon: Pray for the air of heaven, the fruits of the earth, the trees, the vines, and for every fruit-bearing tree in all the world, that Christ our God may bless them, bring them to perfection in peace without harm, and forgive us our sins.", ar: "الشماس: أُطلبوا عن أهوية السماء، وثمرات الأرض والشجر والكروم، وكل شجرة مثمرة في كل المسكونة، لكي يباركها المسيح إلهنا، ويكملها سالمة بغير ألم، ويغفر لنا خطايانا." } },
      { kind: 'rubric', text: { en: "People: Lord have mercy (3).", ar: "الشعب: يا ربُّ إرحَم (3)." } },
      { kind: 'rubric', text: { en: "The three litanies may be combined as follows:", ar: "أو تقال الثلاث أواشي معاً:" } },
      { kind: 'rubric', text: { en: "Priest: Graciously accord, O Lord, to bless the air of heaven, the fruits of the earth, the waters of the river, the seeds, the herbs, and the plants of the field this year.", ar: "الكاهن: تفضل يا رب أهوية السماء وثمرات الأرض صعود مياه الأنهار والزروع والعشب ونبات الحقل في هذه السنة، باركها." } },
      { kind: 'rubric', text: { en: "Deacon: Pray for the air of heaven, the fruits of the earth, the rising of the waters of the rivers, the seeds, the herbs, and the plants of the field, that Christ our God may bless them, have compassion on His creation which His hands have made, and forgive us our sins.", ar: "الشماس: أُطلبوا عن أهوية السماء، وثمرات الأرض، وصعود مياه الأنهار، والزروع والعشب ونبات الحقل، في هذه السنة لكي يباركها المسيح إلهنا، ويتحنن على جبلته التي صنعتها يداه، ويغفر لنا خطايانا." } },
      { kind: 'rubric', text: { en: "People: Lord have mercy (3).", ar: "الشعب: يا ربُّ إرحَم (3)." } },
      { kind: 'rubric', text: { en: "After any one of the litanies, the priest continues with the following:", ar: "وبعد كل أوشية يكمل الكاهن قائلاً:" } },
      { kind: 'rubric', text: { en: "Priest: Raise them to their measure according to Your grace. Give joy to the face of the earth. May its furrows be abundantly watered and its fruits be plentiful.", ar: "الكاهن: اصعِدْها كمقدارِها كنعمَتِكَ، فَرِّحْ وجهَ الأرضِ، ليُرْوَ حرثُها ولتكثرَ أثمارُها." } },
      { kind: 'rubric', text: { en: "Prepare it for sowing and harvesting. Manage our lives as deemed fit.", ar: "أعِدَّها للزرعِ والحصادِ، ودَبِّر حياتَنا كما يليق." } },
      { kind: 'rubric', text: { en: "Bless the crown of the year with Your goodness for the sake of the poor of Your people, the widow, the orphan, the traveler, the stranger, and for the sake of all of us who entreat You and seek Your holy name.", ar: "بَارِكْ إكليلَ السنةِ بصلاحِكَ، من أجلِ فقراءِ شعبِكَ، من أجلِ الأرملةِ واليتيمِ والغريبِ والضيفِ، ومن أجلِنا كُلِّنا نحنُ الذين نرجوكَ ونطلبُ إسمَكَ القدوس." } },
      { kind: 'rubric', text: { en: "For the eyes of everyone wait upon You, for You give them their food in due season.", ar: "لأن أعينَ الكلِّ تترجاكَ، لأنَّكَ أنتَ الذي تُعطِيهم طعامَهم في حينٍ حسنٍ." } },
      { kind: 'rubric', text: { en: "Deal with us according to Your goodness, O You who give food to all flesh. Fill our hearts with joy and gladness, that we too, having sufficiency in everything always, may abound in every good deed.", ar: "إصنع معنا حَسَبَ صلاحِكَ، يا مُعطِياً طعاماً لكلِّ جسدٍ. املأ قلوبَنا فرحاً ونعيماً، لكي نحنُ أيضاً إذ تكونَ لنا الكفايةُ في كلِّ شيءٍ، كلَّ حينٍ، نزدادَ في كلِّ عملٍ صالحٍ." } },
      { kind: 'rubric', text: { en: "People: Lord have mercy.", ar: "الشعب: يا ربُّ إرحَم." } },
      { kind: 'rubric', text: { en: "Priest: Remember, O Lord, those who have brought unto You these gifts, those on whose behalf they have been brought, and those by whom they have been brought. Give them all the heavenly reward.", ar: "الكاهن: أذكر يا رب الذين قدموا لك هذه القرابين، والذين قدمت عنهم، والذين قدمت بواسطتهم، اعطهم كلهم الأجر السمائي." } },
      { kind: 'rubric', text: { en: "Deacon: Pray for these holy and precious gifts, our sacrifices, and those who have brought them.", ar: "الشماس: صلوا من أجل هذه القرابين المقدسة الكريمة، وتقدماتنا، والذين قدموها." } },
      { kind: 'rubric', text: { en: "People: Lord have mercy.", ar: "الشعب: يا ربُّ إرحَم." } },
      { kind: 'heading', text: { en: "The Commemoration of the Saints", ar: "مجمع القديسين" } },
      { kind: 'prayer', text: { en: "As this, O Lord, is the command of Your only-begotten Son, that we share in the commemoration of Your saints, graciously accord, O Lord, to remember all the saints who have pleased You since the beginning:", ar: "لأن هذا يا رب هو أمر إبنك الوحيد، أن نشترك في تذكار قديسيك. تفضل يا رب، أن تذكر جميع القديسين الذين أرضوك منذ البدء." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "our holy fathers the patriarchs, the prophets, the Apostles, the preachers, the evangelists, the martyrs, the confessors, and all the spirits of the righteous perfected in the faith.", ar: "آباءنا الأطهار رؤساء الآباء والأنبياء، والرسل والمبشرين والإنجيليين، والشهداء والمعترفين، وكل أرواح الصديقين، الذين كملوا في الإيمان." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Most of all, the pure, full-of-glory, ever-virgin, holy Theotokos, Saint Mary, who truly gave birth to God the Logos.", ar: "وبالأكثر القديسة المملوءة مجداً، العذراء كل حين والدة الإله القديسة الطاهرة مريم، التي ولدت الله الكلمة بالحقيقة." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "And Saint John the forerunner, baptist, and martyr; Saint Stephen the archdeacon and protomartyr; the beholder-of-God, Saint Mark the Evangelist, the apostle and martyr;", ar: "والقديس يوحنا السابق الصابغ والشهيد، والقديس إستفانوس رئيس الشمامسة وأول الشهداء، وناظر الإله الإنجيلى مرقس الرسول الطاهر والشهيد." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "the patriarch Saint Severus; our teacher Dioscorus; Saint Athanasius the Apostolic; Saint Peter, the holy martyr and high priest;", ar: "والبطريرك القديس ساويرس، ومعلمنا ديوسقورس، والقديس أثناسيوس الرسولي، والقديس بطرس الشهيد ورئيس الكهنه." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Saint John Chrysostom; Saint Theodosius; Saint Theophilus; Saint Demetrius; Saint Cyril; Saint Basil; Saint Gregory the Theologian; Saint Gregory the Wonderworker; Saint Gregory the Armenian;", ar: "والقديس يوحنا ذهبي الفم، والقديس ثاودوسيوس، والقديس ثيئوفيلوس، والقديس ديمتريوس، والقديس كيرلس، والقديس باسيليوس، والقديس اغريغوريوس الناطق بالإلهيات، والقديس اغريغوريوس صانع العجائب، والقديس اغريغوريوس الأرمني." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "the three hundred and eighteen assembled at Nicea; the one hundred and fifty at Constantinople; and the two hundred at Ephesus;", ar: "والثلاثمائة والثمانية عشر المجتمعين بنيقية، والمئة والخمسين بالقسطنطينية، والمائتين بأفسس." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "our righteous father, the great Abba Anthony; the righteous Abba Paul; the three saints Abba Macarii and all their children, the cross-bearers;", ar: "وأبانا الصديق العظيم أنبا أنطونيوس، والبار أنبا بولا، والثلاثة أنبا مقارات القديسين، وجميع أولادهم لُباس الصليب." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "our father Abba John the hegumen; our righteous father Abba Pishoy, the perfect man, the beloved of our good Savior.", ar: "وأبانا أنبا يؤأنس القمص، وأبانا أنبا بيشوي البار الرجل الكامل، حبيب مخلصنا الصالح." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'rubric', text: { en: "If the priest chooses, he may add the following:", ar: "إذ أراد يقول:" } },
      { kind: 'prayer', text: { en: "Our father Abba Paul of Tammoh and Ezekiel his disciple; my lords, the Roman fathers Saints Maximus and Dometius; the Forty-nine Martyrs; the elders of Shiheet; the strong saint Abba Moses; John Kame the priest; our father Abba Daniel the hegumen; our father Abba Isidore the priest; our father Abba Pachom of the Koinonia, and Theodore his disciple; our father Abba Shenoute the archmandrite, and Abba Wesa his disciple;", ar: "وأبانا أنبا بولا الطموهي، وحزقيال تلميذه، وسيدي الأبوين القديسين الروميين مكسيموس ودوماديوس، والتسعة والأربعين شهيداً شيوخ شيهيت، والقوي القديس أنبا موسى، ويحنس كاما القس. وأبانا أنبا دانيال القمص، وأبانا أنبا إيسيذوروس القس، وأبانا أنبا باخوم أب الشركة، وتادرس تلميذه، وأبانا أنبا شنودة رئيس المتوحدين، وأنبا ويصا تلميذه." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "and all the choir of Your saints, through whose prayers and supplications have mercy on us all and save us, for the sake of Your holy name, which is called upon us.", ar: "وكل مصاف قديسيك، هؤلاء الذين بسؤالاتهم وطلباتهم، إرحمنا كلنا معاً. وانقذنا من أجل إسمك القدوس الذي دُعي علينا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Let those who read, recite the names of our holy fathers, the patriarchs who have fallen asleep. O Lord repose their souls, and forgive us our sins.", ar: "القارِئونَ فليقولوا أسماءَ آبائِنا القِدِّيسينَ البطارِكَةِ الذِينَ رَقَدوا. الربُّ يُنيِّحُ نُفُوسَهُم أجمعينَ، ويغفِرُ لَنا خَطايانا." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'prayer', text: { en: "May their holy blessing be with us. Amen.", ar: "برَكَتُهُم المقدسةُ تكونُ مَعَنا. آمين." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Glory to You, O Lord. Lord have mercy. Lord have mercy. Lord, bless us. Lord, repose them. Amen.", ar: "المجدُ لكَ يا رب، (يا ربُّ لكَ المجدُ). يا ربُّ إرحَم. يا ربُّ إرحَم. يا ربُّ بارِكْنا. يا رب نَيِّحْهُم. آمين." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'heading', text: { en: "The Diptych", ar: "ترحيم" } },
      { kind: 'prayer', text: { en: "Remember also, O Lord, all those who have fallen asleep and reposed in the priesthood and in all the orders of the laity.", ar: "اذكر أيضاً يا رب كل الذين رقدوا، وتنيحوا في الكهنوت، والذين في كل طغمة العلمانيين." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Graciously, O Lord, repose all their souls in the bosom of our holy fathers Abraham, Isaac, and Jacob.", ar: "تفضل يا رب نيح نفوسهم جميعاً في حضن آبائنا القديسين، إبراهيم وإسحق ويعقوب." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Sustain them in a green pasture, by the water of rest in the Paradise of joy,", ar: "عُلهُم في موضع خضرة على ماء الراحة في فردوس النعيم." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "the place out of which grief, sorrow, and groaning have fled away in the light of Your saints.", ar: "الموضع الذي هرب منه الحزن والكآبة والتنهد في نور قديسيك." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'rubric', text: { en: "(Or the following diptych from St. Cyril’s liturgy)", ar: "(أو يقول الترحيم الآتي من القداس الكيرلسي)" } },
      { kind: 'prayer', text: { en: "Those, O Lord, and everyone whose names we have mentioned; and those whose names we have not mentioned,", ar: "وهؤلاء وكل أحد، يا رب، الذين ذكرنا أسماءهم،" }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "those whom each one has in mind and those who are not in our minds;", ar: "والذين لم نذكرهم الذين في فكر كل واحد منا، والذين ليسوا في فكرنا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "and those who have fallen asleep and reposed in the faith of Christ.", ar: "الذين رقدوا، وتنيحوا في الإيمان بالمسيح." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'rubric', text: { en: "(The priest mentions the departed)", ar: "(يذكر الكاهن الراقدين)" } },
      { kind: 'prayer', text: { en: "Graciously, O Lord, repose all their souls in the bosom of our holy fathers Abraham, Isaac, and Jacob.", ar: "تفضَّلْ يا ربُّ نَيِّح نُفُوسَهُم أجمعينَ في حِضِنِ آبائِنا القِدِّيسينَ، إبراهيمَ وإسحقَ ويعقوبَ." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Sustain them in a green pasture, by the water of rest in the Paradise of joy,", ar: "عُلهُم في مَوْضِعِ خُضرةٍ على ماءِ الرَّاحةِ في فِردُوسِ النَّعيمِ." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "the place out of which grief, sorrow, and groaning have fled away in the light of Your saints.", ar: "الموْضِعِ الذي هَرَبَ مِنْهُ الحُزنُ والكآبَةُ والتنَهُّدُ في نورِ قدِّيسيكَ." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Pray for our fathers and brethren who have fallen asleep and reposed in the faith of Christ since the beginning our holy fathers, the archbishops, our fathers the bishops, our fathers the hegumens, our fathers the priests, our brethren the deacons, our fathers the monks, and our fathers the laymen, and for the full repose of the Christians.", ar: "أُطلبوا عن آبائنا واخوتنا الذين رقدوا، وتنيحوا في الإيمان بالمسيح منذ البدء. آبائنا القديسين رؤساء الأساقفة، وآبائنا الأساقفة، وآبائنا القمامصة، وآبائنا القسوس، واخوتنا الشمامسة، وآبائنا الرهبان، وآبائنا العلمانيين، وعن نياح كل المسيحيين." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'prayer', text: { en: "That Christ our God may repose all their souls in the Paradise of joy, and we too, accord mercy unto us, and forgive us our sins.", ar: "لكي المسيح إلهنا ينيح نفوسهم أجمعين في فردوس النعيم، ونحن أيضاً يصنع معنا رحمة، ويغفر لنا خطايانا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Lord have mercy.", ar: "يا ربُّ إرحَم." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'heading', text: { en: "Those, O Lord", ar: "أولئك يا رب" } },
      { kind: 'prayer', text: { en: "Those, O Lord, whose souls You have taken, repose them in the Paradise of joy, in the region of the living forever, in the heavenly Jerusalem—in that place.", ar: "أولئك يا رب، الذين أخذت نفوسهم، نيحهم في فردوس النعيم، في كورة الأحياء إلى الأبد، في أورشليم السمائية، في ذلك الموضع." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "And we too, who are sojourners in this place, keep us in Your faith, and grant us Your peace unto the end.", ar: "ونحن أيضاً الغرباء في هذا المكان، إحفظنا في إيمانك، وأنعم لنا بسلامك إلى التمام." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "As it was and shall be, it is from generation to generation, and unto all the ages of the ages. Amen.", ar: "كما كان وهكذا يكون، من جيل إلى جيل، وإلى دهر الدهور. آمين." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'heading', text: { en: "Lead Us", ar: "اهدنا" } },
      { kind: 'prayer', text: { en: "Lead us throughout the way into Your kingdom,", ar: "وإهدنا إلى ملكوتك." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "that as in this, so also in all things, Your great and holy name be glorified, blessed, and exalted in everything, honored and blessed with Jesus Christ, Your beloved Son, and the Holy Spirit.", ar: "لكي وبهذا، كما أيضاً في كل شيء، يتمجد ويتبارك، ويرتفع إسمك العظيم القدوس، في كل شيء، كريم ومبارك، مع يسوع المسيح إبنك الحبيب والروح القدس." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Peace be with all.", ar: "السلام للكل." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "And with your spirit.", ar: "ولروحك أيضاً." }, label: { en: "People", ar: "الشعب" } }
    ],
  },
  {
    id: "basil-communion",
    title: { en: "Fraction, Communion & Dismissal", ar: "القسمة والتناول والانصراف" },
    blocks: [
      { kind: 'heading', text: { en: "Introduction to the Fraction", ar: "مقدمة القسمة" } },
      { kind: 'prayer', text: { en: "Again, let us give thanks to God the Pantocrator, the Father of our Lord, God, and Savior Jesus Christ,", ar: "وأيضاً فلنشكر الله ضابط الكل، أبا ربنا وإلهنا ومخلصنا يسوع المسيح." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "for He also has made us worthy now to stand in this holy place, to lift up our hands, and to serve His holy name.", ar: "لأنه جعلنا أهلاً الآن أن نقف في هذا الموضع المقدس، ونرفع أيدينا إلى فوق، ونخدم إسمه القدوس." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Let us also ask Him to make us worthy of the communion and partaking of His divine and immortal Mysteries.", ar: "هو أيضاً فلنسأله أن يجعلنا مستحقين لشركة وإصعاد أسراره الإلهية غير المائتة." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Amen.", ar: "آمين." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "The holy Body—", ar: "الجسد المقدس." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "We worship Your holy Body—", ar: "نسجد لجسدك المقدس." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "and the precious Blood—", ar: "والدم الكريم." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "and Your precious Blood.", ar: "ودمك الكريم." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "of His Christ, the Pantocrator, the Lord our God.", ar: "اللذين لمسيحه، الضابط الكل الرب إلهنا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Amen. Amen. Pray.", ar: "آمين. آمين. صلوا." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'prayer', text: { en: "Lord have mercy.", ar: "يا ربُّ إرحَم." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Peace be with all.", ar: "السلام للكل." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "And with your spirit.", ar: "ولروحك أيضاً." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'heading', text: { en: "The Fraction", ar: "القسمة" } },
      { kind: 'prayer', text: { en: "O Master, Lord our God, the Great, the Eternal, wondrous in glory;", ar: "أيها السيدُ الربُّ، إلهُنا العظيمُ الأبديُ، والمتَعَجَّبُ مِنهُ بالمجدِ." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "keeping His covenant and His mercy to those who love Him with all their heart;", ar: "حافظُ عهدِهِ ورحمتِهِ للذينَ يحبُّونَه بكلِّ قلبِهِم." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "who has given to us redemption from sins through His only-begotten Son, Jesus Christ our Lord, the life of everyone,", ar: "الذي أعطانا الخلاصَ من خطايانا، بإبنِهِ الوحيدِ يسوعَ المسيحِ ربِّنا حياةِ كلِّ أحدٍ." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "the help of those who flee to Him, the hope of those who cry out to Him;", ar: "يا مُعِينَ الملتجئينَ إليهِ، ورجاءَ الذينَ يصرخُونَ نحوَهُ." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "before whom stand thousands of thousands and ten thousand times ten thousand holy angels and archangels,", ar: "الذي يَقفُ أمامَه ألوفُ ألوفِ وربواتُ ربواتِ الملائكةِ ورؤساءِ الملائكةِ المقدسينَ." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "the Cherubim and the Seraphim, and all the innumerable host of the heavenly powers.", ar: "الشاروبيمُ والسِّرافيمُ وكلُّ الجمعِ غير المُحصَى الذي للقواتِ السمائيةِ." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "O God, who have sanctified these gifts which are set forth through the coming down upon them of Your Holy Spirit, You have purified them.", ar: "اللهُمَّ الذي قدَّسَ هذهِ القرابينَ الموضُوعَةَ بحلولِ روحِكَ القدوسِ عليها وطَهَّرتها." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Purify us also, our Master, from our sins, the hidden and manifest, and every thought which is not pleasing to Your goodness; O God, the Lover of Mankind, may it be far from us.", ar: "طَهِّرْنا نحنُ أيضاً يا سيِّدَنا، من خطايانا الخفيةِ والظاهرةِ. وكلُّ فكرٍ لا يُرضِي صلاحَكَ، يا اللهُ محبَّ البشرِ، فليَبعُدْ عنا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Purify our souls, our bodies, our spirits, our hearts, our eyes, our understanding, our thoughts, and our consciences,", ar: "طهِّرْ نفوسَنا، وأجسادَنا، وأرواحَنا، وقلوبَنا، وعيونَنا، وأفهامَنا، وأفكارَنا، ونياتَنا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "so that, with a pure heart, an enlightened soul, an unashamed face, a faith unfeigned, a perfect love, and a firm hope,", ar: "لكي بقلبٍ طاهرٍ، ونفسٍ مُستَنيرةٍ، ووجهٍ غيرِ مخزيٍّ، وإيمانٍ بلا رياءٍ، ومحبةٍ كاملةٍ، ورجاءٍ ثابتٍ." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "we may dare with boldness, without fear, to pray to You, O God, the holy Father who are in the heavens, and say:", ar: "نَجرُؤَ بدالةٍ، بغيرِ خوفٍ، أن نطلبَ إليكَ، يا اللهُ الآبُ القدوسُ الذي في السمواتِ، ونقول:" }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "“Our Father ....”", ar: "\"أبانا الذي ... \"" }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Our Father who art in heaven, hallowed be Thy name. Thy kingdom come. Thy will be done, on earth as it is in heaven. Give us this day our daily bread; and forgive us our trespasses, as we forgive those who trespass against us; and lead us not into temptation, but deliver us from the evil one. In Christ Jesus our Lord, for Thine is the kingdom and the power and the glory forever. Amen.", ar: "أبانا الذي في السموات، ليتقدس إسمك. ليأت ملكوتك. لتكن مشيئتك، كما في السماء كذلك على الأرض. خبزنا كفافنا أعطنا اليوم. وأغفر لنا ذنوبنا، كما نغفر نحن أيضاً للمذنبين إلينا. ولا تدخلنا في تجربة، لكن نجنا من الشرير. بالمسيح يسوع ربنا، لأن لك الملك والقوة والمجد إلى الأبد. آمين." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'heading', text: { en: "Our Father", ar: "أبانا الذي في السموات" } },
      { kind: 'prayer', text: { en: "Our Father who art in heaven, hallowed be Thy name. Thy kingdom come. Thy will be done, on earth as it is in heaven. Give us this day our daily bread; and forgive us our trespasses, as we forgive those who trespass against us; and lead us not into temptation, but deliver us from the evil one. In Christ Jesus our Lord, for Thine is the kingdom and the power and the glory forever. Amen.", ar: "أبانا الذي في السموات، ليتقدس إسمك. ليأت ملكوتك. لتكن مشيئتك، كما في السماء كذلك على الأرض. خبزنا كفافنا أعطنا اليوم. وأغفر لنا ذنوبنا، كما نغفر نحن أيضاً للمذنبين إلينا. ولا تدخلنا في تجربة، لكن نجنا من الشرير. بالمسيح يسوع ربنا، لأن لك الملك والقوة والمجد إلى الأبد. آمين." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'heading', text: { en: "Prayers After the Fraction", ar: "صلوات بعد القسمة" } },
      { kind: 'rubric', text: { en: "The Prayer After “Our Father”", ar: "صلاة بعد \"أبانا الذي\"" } },
      { kind: 'prayer', text: { en: "Yea, we ask You, O good Father who love goodness, lead us not into temptation, nor let any iniquity rule over us,", ar: "نعم نسألك أيها الآب القدوس الصالح محب الصلاح، لا تدخلنا في تجربة، ولا يتسلط علينا إثم." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "but deliver us from worthless works and from the thoughts, motions, sights, and touch thereof.", ar: "لكن نجنا من الأعمال غير النافعة وأفكارها وحركاتها ومناظرها وملامسها." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Destroy the tempter and drive him away. Rebuke also his movements implanted in us, and cut off from us all impulses which drag us into sin,", ar: "والمجرب أبطله وأطرده عنا وإنتهز أيضاً حركاته المغروسة فينا. وإقطع عنا الأسباب التي تسوقنا إلى الخطية." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "and deliver us by Your holy power in Christ Jesus our Lord.", ar: "ونجنا بقوتك المقدسة، بالمسيح يسوع ربنا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Through whom …", ar: "هذا الذي من قبله ..." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Bow your heads to the Lord.", ar: "إحنوا رؤوسكم للربِ." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'prayer', text: { en: "Before You, O Lord.", ar: "أمامك يا ربُ." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'rubric', text: { en: "The Prayer of Submission to the Father", ar: "صلاة خضوع للآب" } },
      { kind: 'prayer', text: { en: "The graces of the beneficence of Your only-begotten Son, our Lord, God, and Savior Jesus Christ, are now fulfilled.", ar: "كملت نعم إحسان إبنك الوحيد ربنا وإلهنا ومخلصنا يسوع المسيح." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "We have confessed His saving Passion; we have proclaimed His Death; we have believed in His Resurrection; and the Mystery is accomplished.", ar: "إعترفنا بآلامه المخلصة، بشرنا بموته، أمنا بقيامته، وكمل السر." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "We give thanks to You, O Lord God the Pantocrator, for Your mercy is great upon us, for You have prepared for us those things which the angels desire to behold.", ar: "نشكرك أيها الرب الإله ضابط الكل، لأن رحمتك عظيمة علينا، إذا أعددت لنا ما تشتهي الملائكة أن تطلع عليه." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "We ask and entreat Your goodness, O Lover of Mankind, that, since You have purified us all, You join us to Yourself through our partaking of Your divine Mysteries,", ar: "نسأل ونطلب من صلاحك يا محب البشر لكي إذ طهرتنا كلنا توحدنا بك من جهة تناولنا من أسرارك الإلهية." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "that we may become filled with Your Holy Spirit, confirmed in Your upright faith. Having been filled with the longing for Your true love, may we speak of Your glory at all times in Christ Jesus our Lord.", ar: "لكي نكون مملوئين من روحك القدوس، وثابتين في إيمانك المستقيم، ومملوئين من شوق محبتك الحقيقية، وننطق بمجدك كل حين، بالمسيح يسوع ربنا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Through whom …", ar: "هذا الذي من قبله ..." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Let us attend in the fear of God. Amen.", ar: "أنصتوا بخوف الله. آمين." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'prayer', text: { en: "Peace be with all.", ar: "السلام للكل." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "And with your spirit.", ar: "ولروحك أيضاً." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'rubric', text: { en: "The Prayer of Absolution to the Father", ar: "صلاة تحليل للآب" } },
      { kind: 'prayer', text: { en: "O Master, Lord God the Pantocrator, Healer of our souls, our bodies, and spirits,", ar: "أيها السيد الرب الإله ضابط الكل، شافي نفوسنا وأجسادنا وأرواحنا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "You are He who said to our father Peter, from the mouth of Your only-begotten Son, our Lord, God, and Savior Jesus Christ,", ar: "أنت الذي قلت أبينا بطرس، من فم إبنك الوحيد ربنا وإلهنا ومخلصنا يسوع المسيح:" }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "“You are Peter, and on this rock I will build My Church, and the gates of Hades shall not prevail against it.", ar: "\"أنت هو بطرس وعلى هذه الصخرة أبني كنيستي. وأبواب الجحيم لن تقوى عليها." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "I will give you the keys of the kingdom of the heavens, and whatever you bind on earth shall be bound in the heavens, and whatever you loose on earth shall be loosed in the heavens.”", ar: "وأعطيك مفاتيح ملكوت السموات، وما ربطته على الأرض يكون مربوطاً في السموات، وما حللته على الأرض يكون محلولاً في السموات.\"" }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Therefore, O Lord, let Your servants, my fathers and my brethren and my own weakness, be absolved by my mouth, through Your Holy Spirit, O Good One and Lover of Mankind.", ar: "فيكن يا سيد، عبيدك، آبائي وإخوتي وضعفي، محاللين من فمي بروحك القدوس، أيها الصالح محب البشر." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "O God, who take away the sin of the world, hasten to accept the repentance of Your servants, for a light of understanding and forgiveness of sins.", ar: "اللهُمَّ يا حامل خطية العالم، إبدأ بقبول توبة عبيدك منهم، نوراً للمعرفة وغفراناً للخطايا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "For You are a compassionate and merciful God; You are patient; Your mercy is great and true.", ar: "لأنك أنت إله رؤوف رحوم. أنت طويل الأناة كثير الرحمة وبار." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "If we have sinned against You, either by word or by deed, pardon and forgive us, as a Good One and Lover of Mankind.", ar: "وإن كنا قد أخطأنا إليك بالقول أو بالفعل، فسامح وإغفر لنا، كصالح ومحب للبشر." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "O God, absolve us, and absolve all Your people.", ar: "اللهُمَّ حاللنا وحالل كل الشعب." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'rubric', text: { en: "If he wishes, the priest mentions the living and the dead, then continues, saying:", ar: "وهنا يذكر من يريد أن يذكره من الأحياء والراقدين. ثم يكمل قائلاً:" } },
      { kind: 'prayer', text: { en: "Remember, O Lord, my own weakness and forgive my many sins, and where transgression has abounded, let Your grace be multiplied in abundance. Because of my own sins and the abomination of my heart, deprive not Your people of the grace of Your Holy Spirit.", ar: "إذكر يا رب ضعفي أنا أيضاً، وإغفر لي خطاياي الكثيرة، وحيث كثر الآثم فلتكثر هناك نعمتك، ومن أجل خطاياي خاصة ونجاسات قلبي، لا تمنع شعبك من نعمة روحك القدوس." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "O God, absolve us, and absolve all Your people from every sin, and from every curse, and from every denial, and from every false oath, and from every encounter with the heretics and the heathen.", ar: "اللهُمَّ حاللنا وحالل كل شعبك، من كل خطية ومن كل لعنة، ومن كل جحود، ومن كل يمين كاذب، ومن كل ملاقاة الهراطقة الوثنين." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "O our Master, grant us a reason and power and understanding to flee from any evil deed of the adversary, and grant us to do what is pleasing to You at all times.", ar: "أنعم لنا يا سيدنا بعقل وقوة وفِهم لنهرب إلى التمام من كل أمر رديء للمضاد، وإمنحنا أن نصنع مرضاتك كل حين." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Inscribe our names with all the choir of Your saints in the kingdom of the heavens in Christ Jesus our Lord.", ar: "أكتب أسمائنا مع كل صفوف قديسيك في ملكوت السموات بالمسيح يسوع ربنا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Through whom …", ar: "هذا الذي من قبله ..." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Remember, O Lord, our assemblies; bless them.", ar: "أذكر يا ربُّ إجتماعاتنا، باركها." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Saved. Amen. And with your spirit. In the fear of God, let us attend.", ar: "خلَصْتَ حقاً، ومع رُوحِكَ، ننصِتُ بخوفِ الله." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'prayer', text: { en: "Amen.", ar: "آمين." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Lord have mercy (3).", ar: "يا ربُّ إرحَم (3)." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'heading', text: { en: "The Confession", ar: "الإعتراف" } },
      { kind: 'prayer', text: { en: "The Holies for the holy.", ar: "القُدساتُ للقِدِّيسينَ." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Blessed be the Lord Jesus Christ, the Son of God; the sanctification is by the Holy Spirit. Amen.", ar: "مٌبارَكٌ الربُّ يسوعُ المسيحُ إبنُ اللهِ، وقُدُّوسٌ الرُّوحُ القُدُسُ. آمين." } },
      { kind: 'prayer', text: { en: "One is the Holy Father, one is the Holy Son, one is the Holy Spirit. Amen.", ar: "واحد هو الآب القدوس. واحد هو الإبن القدوس. واحد هو الروح القدس. آمين." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'rubric', text: { en: "Or they say:", ar: "أو يقولوا:" } },
      { kind: 'prayer', text: { en: "One is the All-Holy Father, one is the All-Holy Son, one is the All-Holy Spirit. Amen.", ar: "واحد الآب الكلي القدوس. واحد الإبن الكلي القدوس. واحد الروح القدس الكلي. آمين." } },
      { kind: 'prayer', text: { en: "Peace be with all.", ar: "السلام للكل." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "And with your spirit.", ar: "ولروحك أيضاً." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "The holy Body and the precious, true Blood of Jesus Christ, the Son of our God. Amen.", ar: "جسدٌ مُقدَّسٌ، ودمٌ كريمٌ حقيقيٌّ، ليسوعَ المسيحِ إبنِ إلَهِنا. آمين." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Amen.", ar: "آمين." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "The holy, precious Body and the true Blood of Jesus Christ, the Son of our God. Amen.", ar: "مُقدَّسٌ وكَريمٌ جسدٌ ودمٌ حقيقيُّ، ليسوعَ المسيحِ إبنِ إلَهِنا. آمين." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Amen.", ar: "آمين." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "The Body and the Blood of Emmanuel our God; this is true. Amen.", ar: "جسدُ ودمُ عمانوئيلَ إلَهِنا هذا هو بالحقيقةِ. آمين." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Amen. I believe.", ar: "حقاً. أؤمن." }, label: { en: "People", ar: "الشعب" } },
      { kind: 'prayer', text: { en: "Amen. Amen. Amen. I believe, I believe, I believe and confess to the last breath", ar: "آمين. آمين. آمين. أؤمن. أؤمن. أؤمن. واعترف إلى النفس الأخير." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "that this is the life-giving Flesh that Your only-begotten Son, our Lord, God, and Savior Jesus Christ, took from our Lady, the Lady of us all, the holy Theotokos, Saint Mary.", ar: "أن هذا هو الجسد المحيي، الذي أخذه إبنك الوحيد الجنس، ربنا وإلهنا ومخلصنا يسوع المسيح من سيدتنا وملكتنا كلنا والدة الإله القديسة الطاهرة مريم." } },
      { kind: 'prayer', text: { en: "He made It one with His divinity without mingling, without confusion, and without alteration.", ar: "وجعله واحداً مع لاهوته بغير إختلاط ولا أمتزاج ولا تغيير." } },
      { kind: 'prayer', text: { en: "He confessed the good confession before Pontius Pilate.", ar: "وإعترف الإعتراف الحسن أمام بيلاطس البنطي." } },
      { kind: 'prayer', text: { en: "He gave It up for us upon the holy wood of the Cross, of His own will, for us all.", ar: "وسلمه عنا على خشبة الصليب المقدسة، بإرادته وحده عنا كلنا." } },
      { kind: 'prayer', text: { en: "Truly I believe that His divinity parted not from His humanity for a single moment, nor a twinkling of an eye;", ar: "بالحقيقة أؤمن، أن لاهوته لم يفارق ناسوته لحظة واحدة ولا طرفة عين." } },
      { kind: 'prayer', text: { en: "given for us for salvation, remission of sins, and eternal life to those who partake of Him.", ar: "يعطى عنا خلاصاً وغفراناً للخطايا وحياة أبدية لمَنْ يتناول منه." } },
      { kind: 'prayer', text: { en: "I believe, I believe, I believe that this is true. Amen.", ar: "أؤمن. أؤمن. أؤمن. أن هذا هو بالحقيقة. آمين." } },
      { kind: 'prayer', text: { en: "Amen. Amen. Amen. I believe, I believe, I believe that this is true. Amen.", ar: "آمين، آمين، آمين. أؤمن، آؤمن، آؤمن. أن هذا هو بالحقيقة. آمين." }, label: { en: "Deacon", ar: "الشماس" } },
      { kind: 'prayer', text: { en: "Pray for us and for all Christians who said to us concerning them, “Remember us in the house of the Lord.”", ar: "اُطلبوا عنا وعن كلِّ المسيحيينَ الذينَ قالوا لنا من أجلهِم، \"أذكرونا في بيت الرب.\"" } },
      { kind: 'prayer', text: { en: "The peace and love of Jesus Christ be with you. Sing, “Alleluia.”", ar: "سلامُ ومحبةُ يسوعَ المسيحِ معكُم. رتلوا بنشيد: \"هلليلويا.\"" } },
      { kind: 'prayer', text: { en: "Pray for the worthy partaking of the immaculate, heavenly, and holy Mysteries.", ar: "صلُّوا من أجلِ التناولِ باستحقاقٍ من هذه الأسرارِ المقدسةِ الطاهرةِ والسمائيةِ." } },
      { kind: 'prayer', text: { en: "Lord have mercy.", ar: "يا ربُّ إرحَم." } },
      { kind: 'heading', text: { en: "Prayers Before the Distribution", ar: "صلوات قبل التناول" } },
      { kind: 'prayer', text: { en: "Make us all worthy, O our Master, to partake of Your holy Body and Your precious Blood unto the purification of our souls, bodies, and spirits, and unto the remission of our sins and iniquities, that we may be one body and one spirit with You.", ar: "إجعلنا مستحقين كلنا يا سيدنا أن نتناول من جسدك المقدس ودمك الكريم، وطهارة لأنفسنا وأجسادنا وأرواحنا، ومغفرة لخطايانا وآثامنا، لكي نكون جسداً واحداً وروحاً واحداً معك." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Glory to You, with Your good Father and the Holy Spirit, forever. Amen.", ar: "المجد لك مع أبيك الصالح والروح القدس، إلى الأبد. آمين." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Loose, remit, and forgive us, O God, our iniquities which we have committed willingly and which we have committed unwillingly, which we have committed knowingly and which we have committed unknowingly; the hidden and the manifest, O Lord, remit for us, for the sake of Your holy name which is called upon us.", ar: "حل وأغفر وإصفح لنا يا الله عن زلاتنا التي صنعناها بإرادتنا والتي صنعناها بغير إرادتنا، التي فعلناها بمعرفة والتي فعلناها بغير معرفة، الخفية والظاهرة، يا رب إغفرها لنا من أجل أسمك القدوس الذي دُعي علينا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "According to Your mercy, O Lord, and not according to our sins.", ar: "كرحمتك يا رب وليس كخطايانا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Author of life and King of the ages, Logos of God the Father, our Lord, God, and Savior Jesus Christ;", ar: "يا رئيس الحياة وملك الدهور، كلمة الله الآب، ربنا وإلهنا ومخلصنا يسوع المسيح." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "the true Bread which came down from heaven; who give life to those who partake of Him;", ar: "الخبز الحقيقي الذي نزل من السماء، واهب الحياة لمَنْ يتناوله." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "make us worthy, without falling into condemnation, to partake of Your holy Body and Your precious Blood.", ar: "إجعلنا أهلاً، بغير وقوع في دينونة، أن نتناول من جسدك المقدس ودمك الكريم." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "May our partaking of Your holy Mysteries make us one with You unto the end; and bless us.", ar: "وليصبرنا تناولنا من أسرارك المقدسة، واحداً معك إلى الإنقضاء وباركنا." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "You are the Son of God; Yours is the glory, with Him and the Holy Spirit, the Giver of Life, forever. Amen.", ar: "أنت هو إبن الله. لك المجد معه مع الروح القدس المحيي إلى الأبد. آمين." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Our Father ....", ar: "أبانا الذي ..." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "O our Lord Jesus Christ, make us worthy to partake of Your pure Body and Your precious Blood,", ar: "يا ربنا يسوع المسيح، إجعلنا مستحقين أن نتناول من جسدك الطاهر ودمك الكريم." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "without it being condemnation for us.", ar: "ولا يكون تناولنا لنا دينونة." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Rather, as You have said to Your holy disciples, “Take My body and blood for the remission of your sins.”", ar: "لكن كما قلت لتلاميذك الأطهار \"خذوا من جسدي ودمي لمغفرة خطاياكم.\"" }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Likewise, may we have communion with Your holy disciples, partaking of Your life giving Mysteries", ar: "هكذا أيضاً تكون لنا شركة مع تلاميذك الأطهار بتناولنا من أسرارك المحيية." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "that we may be granted remission of our sins and forgiveness of our iniquities and purity for our souls, bodies, and spirits, unto firmness in the faith of Your holy name till the last breath,", ar: "فننال مغفرة لخطايانا، وصفحاً لآثامنا، وطهارةً لأنفسنا وأجسادنا وأرواحنا وثباتاً على الإيمان بإسمك القدوس إلى النفس الأخير." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "through the prayers of our Lady, Saint Mary, and of all Your saints. Amen.", ar: "بطلبات الطاهرة مرتمريم وكافة قديسيك. آمين." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'heading', text: { en: "A Prayer of Thanksgiving", ar: "صلاة شكر" } },
      { kind: 'prayer', text: { en: "Our mouth is filled with gladness and our tongue with rejoicing from our partaking of Your immortal Mysteries, O Lord.", ar: "فَمُنا إمتلأ فَرَحاً، ولِسَانُنا تهليلاً، مِن جِهَةِ تَناوِلِنا مِن أسرارِكَ غيرِ المائِتَةِ يا ربُّ." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "That which an eye has not seen nor ear heard, neither have entered into the heart of man,", ar: "لأنَّ ما لم تَرَهُ عَينٌ، ولم تَسمَعْ بهِ اُذنٌ، ولم يخطُرْ على قَلبِ بشرٍ." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "the things which You, O God, have prepared for those who love Your holy name, and have revealed to the little children of Your holy Church.", ar: "ما أعدَدْتَهُ يا اللهُ لمحِبِّي إسمِكَ القُدُّوسِ، أعلَنتَهُ للأطفالِ الصِغارِ الذِينَ لكنيستِكَ المقدَّسةِ." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Yea, O Father, this is the pleasure before You, for You are merciful.", ar: "نعم أيَّها الآبُ إنَّ هذِهِ هي المسرةُ التي كانت أمامَكَ، لأنَّكَ رَحيمٌ." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "We send up unto You glory and honor, O Father and Son and Holy Spirit,", ar: "ونُرسِلُ لكَ إلى فوقُ المجدَ والإكرامَ، أيها الآبُ والإبنُ والرُّوحُ القُدُسُ." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "now and at all times and unto the age of all ages. Amen.", ar: "الآنَ وكُلَّ أوانٍ وإلى دهرِ الدُّهورَ كُلِّها. آمين." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'heading', text: { en: "The Prayer of Submission to the Father", ar: "صلاة خضوع للآب" } },
      { kind: 'prayer', text: { en: "Your servants, O Lord, who are serving You, entreating Your holy name and bowing down their heads to You,", ar: "عَبيدُكَ يا ربُّ هؤلاءِ الذِينَ يخدُمونَكَ ويَطلُبونَ إسمَكَ القُدُّوسَ ويخضَعُونَ لكَ." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "dwell in them, O Lord, walk among them, aid them in every good deed,", ar: "حِلَّ فِيهِم يا ربُّ وسِرْ بَيْنَهُم، ساعِدهُم في كُلِّ عملٍ صالِحٍ." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "wake their heart from every vile earthly thought,", ar: "أنهِضْ قُلوبَهُم مِن كُلِّ فِكرٍ رَديءٍ أرضيٍ." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "grant them to live and think of what is pertaining to the living and understand the things that are Yours.", ar: "إمنَحْهُم أن يَحيُوا، ويُفَكِّروا في ما للأحيَاءِ، ويَفهَمُوا الذي لكَ." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "Through Your only-begotten Son, our Lord, God, and Savior Jesus Christ,", ar: "بإبنِكَ الوَحِيدِ رَبِّنَا وإلهِنا ومُخَلِّصِنا يَسُوعَ المسيحِ." }, label: { en: "Priest", ar: "الكاهن" } },
      { kind: 'prayer', text: { en: "to whom we and all Your people cry out, saying, “Have mercy upon us, O God, our Savior.”", ar: "هذا الذي نحنُ وكُلُّ شعبِكَ نصرُخُ قائِلينَ: \"إرحمَنا يا اللهُ مُخَلِّصَنا.\"" }, label: { en: "Priest", ar: "الكاهن" } }
    ],
  }
];
